[1224] = {"赞加沼泽的主张：杰出的金色珍珠","\n收集一颗杰出的金色珍珠，并将其交还给盘牙水库中的芬克尔・法格特。","Limitzero"},
[1225] = {"赞加沼泽的主张：奢华的黑珍珠","\n收集一颗奢华的黑珍珠，并将其交还给盘牙水库中的芬克尔・法格特。","Limitzero"},
