[1228] = {"荣誉战斗：地下城（高风险）","\n在菲拉斯的1v1荣誉战斗中消灭3名玩家。你和你的目标都必须处于宝藏猎人：地下城激活状态，才能获得击杀奖励。","Limitzero"},
[1229] = {"荣誉战斗：祖尔格拉布（高风险）","\n在冬泉谷的1v1荣誉战斗中消灭3名玩家。你和你的目标都必须处于宝藏猎人：祖尔格拉布激活状态，才能获得击杀奖励。","Limitzero"},
