[1231] = {"荣誉战斗：奥妮克希亚（高风险）","\n在冬泉谷的1v1荣誉战斗中消灭3名玩家。你和你的目标都必须处于宝藏猎人：奥妮克希亚激活状态，才能获得击杀奖励。","Limitzero"},
[1232] = {"荣誉战斗：黑翼之巢（高风险）","\n在西瘟疫之地的1v1荣誉战斗中消灭3名玩家。你和你的目标必须处于宝藏猎人：黑翼之巢激活状态，才能获得击杀奖励。","Limitzero"},
[1233] = {"荣誉战斗：安其拉（高风险）","\n在西瘟疫之地的1v1荣誉战斗中消灭3名玩家。你和你的目标都必须处于宝藏猎人：安其拉激活状态，才能获得击杀奖励。","Limitzero"},
[1234] = {"荣誉战斗：纳克萨玛斯（高风险）","\n在西瘟疫之地的1v1荣誉战斗中消灭3名玩家。你和你的目标都必须处于宝藏猎人：纳克萨玛斯激活状态，才能获得击杀奖励。","Limitzero"},
