[17838] = {"稀释血槌氏族","\n在南部刀锋山脉消灭血槌食人魔和恐狼。","Limitzero"},
[17839] = {"削弱刀塔氏族","\n在刀锋山脉消灭刀塔食人魔。","Limitzero"},
[17840] = {"袭击食人魔","\n从刀锋山的食人魔那里偷取麦酒。","Limitzero"},
[17841] = {"灾难的配方","\n在刀锋山脉收集恐狼的牙齿和血槌蒸馏手册。","Limitzero"},
[17842] = {"勉为其难","\n在锯齿山脊消灭雷神恶狼和刃翼放血者。","Limitzero"},
[17844] = {"死亡熔炉大扫荡","\n在死亡之门消灭可恶的恶魔。","Limitzero"},
[17845] = {"不遗漏任何怪物","\n在鳞翼沙洲上消灭鳞翼飞蛇，刃喉鞭尾龙和山脊捕猎者。","Limitzero"},
[17846] = {"维克鸦巢的没落","\n在维克哈营地击杀维克鸦人。","Limitzero"},
[17848] = {"维克鸦巢的没落","\n消灭维克鸦人，消除鸦人空灵召唤者的威胁。","Limitzero"},
[17849] = {"水晶收集者","\n\n收集3颗蓝色水晶\n收集3颗红色水晶\n收集3颗黄色水晶","Limitzero"},
[17850] = {"维克鸦巢寻蛋游戏","\n在维克鸦巢收集鸦人的蛋，阻止邪恶鸦人氏族的重生。","Limitzero"},
[17851] = {"熄灭火焰","\n在刀锋山的斯卡尔德周围消灭灼热元素，灼热鬼和滚烫的蜥蜴。","Limitzero"},
[17852] = {"打破巴什伊尔","\n在刀锋山的巴什伊尔码头消灭巴什伊尔奥术师，巴什伊尔法术窃贼和巴什伊尔掠夺者。","Limitzero"},
[17853] = {"捡拾丢失的箭","\n在卢安荒野收回拜龙教徒丢失的箭，以备日后分析。","Limitzero"},
[17854] = {"卢安统治的终结","\n","Limitzero"},
[17856] = {"解除巫妖崇拜","\n在卢安荒野收集拜龙教偷猎者的弓和拜龙教伐木工的斧头。","Limitzero"},
[17857] = {"打破砾石","\n在砾石部族消灭砾石蛮兵和砾石萨满祭司。","Limitzero"},
[17858] = {"砍倒乌鸦林","\n在格里施纳击杀乌鸦林叶须古树，恶鸦和乌鸦林石皮古树。","Limitzero"},
[17859] = {"破解格里施纳之谜","\n调查格里施纳并消灭格里施纳鸦人，阻止他们即将对外域发动的进攻。","Limitzero"},
[17860] = {"从森林到熔炉","\n在乌鸦林为希尔瓦纳的治疗者收集木头。","Limitzero"},
[17861] = {"格里施纳的遗产","\n在格里施纳废墟中发现失落格里施纳遗物，研究它们的起源。","Limitzero"},
[17862] = {"保护铸魔营地：愤怒","\n突袭铸魔营地：愤怒，并在营地易受攻击时消灭其残余部队。","Limitzero"},
[17863] = {"铸魔营地：惊骇大扫荡","\n阻止铸魔营地：惊骇即将进行的屠杀。","Limitzero"},
[17864] = {"水晶怪物","\n消灭由水晶变异的漩涡尖塔怪物。","Limitzero"},
[17865] = {"为纪念碑提供动力","\n收集埃匹希斯水晶来激活古迹。","Limitzero"},
[17866] = {"炽热核心","\n从铸魔营地：惊骇那里收集不稳定的火焰核心。","Limitzero"},
[17867] = {"解体基尔索罗","\n在基尔索罗要塞击败基尔索罗军队。","Limitzero"},
[17869] = {"攻破石拳氏族","\n在火刃废墟击败石拳食人魔。","Limitzero"},
[17870] = {"稀释怪物","\n清除纳格兰人口过剩的塔布羊，裂蹄牛和风鹏。","Limitzero"},
[17871] = {"确保供应","\n从风茅村偷窃物资，削弱蛮兵的力量。","Limitzero"},
[17872] = {"流放者的碎片","\n从堕落的破碎流亡者那里收集古老的风茅项链。","Limitzero"},
[17873] = {"破坏仪式","\n扰乱基尔索罗在沃舒古的仪式。","Limitzero"},
[17874] = {"驱散阴影,土与风","\n驱散徘徊在灵魂平原的诅咒怪物。","Limitzero"},
[17875] = {"拆除维尔埃尼","\n在灵魂平原击败维尔埃尼军队。","Limitzero"},
[17876] = {"文化视角","\n在灵魂平原找到并恢复兽人先祖石板。","Limitzero"},
[17877] = {"沃舒古知识","\n","Limitzero"},
[17878] = {"消灭石拳","\n消灭南风裂谷的石拳食人魔部队。","Limitzero"},
[17879] = {"消除海洋和陆地的涌动","\n消灭哈剌尼盆地中新出现的岩石碾压者和涌动的怪物。","Limitzero"},
[17880] = {"暗血屠杀","\n阻止暗血部队对日泉岗哨的袭击计划。","Limitzero"},
[17881] = {"拦截石拳条款","\n从石拳部族偷取战争物资，防止哈剌尼盆地发生屠杀。","Limitzero"},
[17882] = {"潮汐调查","\n","Limitzero"},
[17883] = {"战槌战争","\n在纳格兰的战槌山消灭战槌术士和战槌蛮兵。","Limitzero"},
[17884] = {"消灭部族","\n在纳格兰的嘲颅废墟消灭战槌萨满祭司和战槌劫掠者。","Limitzero"},
[17885] = {"失落帝国的遗迹","\n在纳格兰的嘲颅废墟的战槌食人魔处收集12枚徽记。","Limitzero"},
[17886] = {"释放先祖","\n","Limitzero"},
[17887] = {"内辛瓦里的遗产","\n在纳格兰消灭大型风鹏，塔布羊食棘者和裂蹄公牛。","Limitzero"},
[17888] = {"恶魔扰乱","\n","Limitzero"},
[17889] = {"死亡暗影的覆灭","\n","Limitzero"},
