[17904] = {"废料场杀戮","\n","Limitzero"},
[17905] = {"青翠藤蔓","\n","Limitzero"},
[17906] = {"日怒杀戮","\n","Limitzero"},
[17907] = {"危险研究","\n","Limitzero"},
[17908] = {"肯瑞瓦的混沌","\n","Limitzero"},
[17909] = {"日怒样式","\n","Limitzero"},
[17910] = {"重建肯瑞瓦","\n","Limitzero"},
[17911] = {"净化空洞","\n","Limitzero"},
[17912] = {"恶魔毁灭","\n","Limitzero"},
[17913] = {"驱逐萨克希斯","\n勇士，萨克希斯积压了太多以太，不受控制地消耗了它的原始能量。他们的跟踪者和袭击者不停地进食，数量惊人地增长。我们必须在虫害蔓延之前立即采取行动!我需要你去堆里杀了萨克希斯。消灭他们狡猾的跟踪者，摧毁贪婪的袭击者。勇士，只有你的技能才能完成这项重要任务。移除这场针对虚空风暴的瘟疫，以便恢复平衡!","Limitzero"},
[17914] = {"净化腐蚀","\n","Limitzero"},
[17915] = {"给切割机充电","\n英雄，我们盟友的切割机需要充电，才能在虚空风暴的恶劣条件下安全运行。如果利用得当，这里丰富的元素能量应该能提供充足的能量。我需要你把你找到的任何不活动的切割机连接到附近的魔法射线。将原始的奥术电流引入电池，直到充满电。让这些机器再次运行将极大地帮助我们在该地区的努力。","Limitzero"},
[17916] = {"面对燃烧军团","\n英雄，军团要塞挤满了我们的敌人。暗影议会术士使用黑暗魔法，而恐怖主宰则召集可怕的军队。愤怒行者和莫尔葛熔魔装备恶魔般的武器来为他们的战争机器提供燃料。我请求你冒险前往军团要塞，直面军团——杀死他们的部队和领导层，使军团要塞陷入混乱。你今天的行动可能会对他们的作战造成毁灭性的打击。","Limitzero"},
[17917] = {"破坏死亡熔炉","\n英雄，军团的死亡熔炉制造出恶魔般的战争机器，在影月肆虐。当召唤者召唤援军时，守护者保护着现场。技师在里面制造怪物。我要求你攻击死亡锻造厂，破坏他们的运作——杀死他们的守护者、召唤者和技师，这样他们的工作就会中断。如果我们能够打破他们的生产力，这将使我们暂时摆脱他们的恐怖。","Limitzero"},
[17918] = {"魔化野兽必须被干掉","\n","Limitzero"},
[17919] = {"令人窒息的军团","\n","Limitzero"},
[17920] = {"魔皮","\n","Limitzero"},
[17921] = {"击退日蚀猛攻","\n","Limitzero"},
[17922] = {"破坏死亡熔炉","\n","Limitzero"},
[17925] = {"吞噬虚空","\n","Limitzero"},
[17926] = {"清理冬泉谷","\n","Limitzero"},
[17927] = {"找回冬泉谷图腾","\n","Limitzero"},
[17928] = {"木喉熊爪","\n","Limitzero"},
[17929] = {"冰火硫磺","\n","Limitzero"},
[17930] = {"通缉：科伦","\n","Limitzero"},
[17931] = {"屠戮鱼人","\n","Limitzero"},
[17933] = {"埃达拉斯","\n","Limitzero"},
[17934] = {"过关斩将","\n","Limitzero"},
[17935] = {"连接过去","\n","Limitzero"},
[17936] = {"海味祸患","\n","Limitzero"},
[18000] = {"霜刃豹计划","\n","Limitzero"},
[18001] = {"冬泉谷狩猎","\n","Limitzero"},
[18002] = {"清理枭兽","\n","Limitzero"},
[18004] = {"冬泉谷的精华","\n","Limitzero"},
[18005] = {"通缉：图雷肯","\n","Limitzero"},
[18006] = {"净化上层精灵","\n","Limitzero"},
[18007] = {"邪恶蓝龙","\n曾经受人尊敬和强大的蓝龙现在已经陷入黑暗的深渊，困扰着这片土地，威胁着那里的居民。英雄，必须恢复平衡。面对深蓝龙崽、深蓝龙人法师和深蓝刃鳞龙人，阻止他们日益增长的恶意。","Limitzero"},
[18008] = {"冬泉谷的终结","\n冬泉谷毛皮，曾经和平的冬泉谷原住民变得越来越咄咄逼人，威胁到该地区的微妙平衡。令人不安的谣言表明，黑暗势力已经占据了主导地位。英雄，你要面对冬泉巢穴守卫、冬泉巨熊怪和冬泉萨满，结束他们被玷污的统治。","Limitzero"},
[18009] = {"冻土的遗物","\n","Limitzero"},
[18011] = {"通缉：冰隆隆","\n","Limitzero"},
[18012] = {"清理冰霜巨人","\n","Limitzero"},
[18013] = {"干掉枭兽","\n","Limitzero"},
[18014] = {"暗语的蔑视","\n暗语峡谷回荡着赫达琳恶魔的恶毒能量。他们的存在是冬泉谷的枯萎病，他们的黑暗魔法渗透到这片土地的精华中。英雄，这些赫达琳恶魔必须在他们的黑暗势力吞噬一切之前被阻止。直面赫达琳屠杀者、赫达琳新兵和危险的赫达琳魔行者，以击退这一迫在眉睫的威胁。","Limitzero"},
[18015] = {"冬泉谷工艺品","\n在冬泉谷冻伤的广袤土地上，隐藏着强大的元素，每个元素都蕴含着该地区的精华。霜槌碎片，远古巨人的遗迹，与这片土地的持久力量产生共鸣。枭兽羽毛，轻盈如雪花，但强劲如狂风，诉说着天空的秘密。最后，赫达琳之心，以一种黑暗、未知的力量脉动，可以解开更深层次的谜团。英雄，收集这些物品，帮助我们揭示冬泉力量的真实本质。","Limitzero"},
[18016] = {"通缉：阿卡里尔","\n","Limitzero"},
[18017] = {"铲除魔爪","\n费伍德，一片曾经生机勃勃的森林，现在被恶魔般的腐败所污染。死木部落在这种恶劣的影响下，造成了严重破坏，加深了森林的腐败。死木萨满祭司、死木复仇者和他们警惕的死木守卫是这场混乱背后的驱动力。英雄，需要你的剑和决心来阻止这个黑暗部落的浪潮，并为费伍德带回希望。","Limitzero"},
[18018] = {"枯木和荒芜","\n费伍德郁郁葱葱的森林正受到威胁。铁木践踏者曾经是林地的守护者，现在却践踏了林地的精髓，而剧毒之水则毒害了该地区的命脉。英雄，大地在呼救。勇敢地面对这些威胁，确保费伍德的自然美景得到保护。","Limitzero"},
[18019] = {"驱散恶魔：驱除碧火","\n恶毒的碧火萨特是被诅咒的过去的余孽，他们的背叛和黑暗魔法遍布费伍德。他们的碧火唤魔者领导着黑暗的仪式，碧火背叛者散步谣言，碧火欺诈者欺骗无辜，他们的统治有可能使森林陷入不可逆转的黑暗。英雄，该你来干预了。驱除碧火萨特的威胁，为受污染的树林带来喘息的机会。","Limitzero"},
[18020] = {"腐蚀元素","\n","Limitzero"},
[18021] = {"通缉：扎祖图尔","\n","Limitzero"},
[18022] = {"毁灭死木","\n","Limitzero"},
[18023] = {"驱散恶魔：碧火的清算","\n","Limitzero"},
[18024] = {"野性狂乱","\n","Limitzero"},
[18026] = {"加德纳尔的阴影","\n","Limitzero"},
[18027] = {"加德纳尔的阴影","\n","Limitzero"},
[18028] = {"净化瘟疫林地","\n剧毒林地，曾经是自然美景的避难所，现在却被一场强大的瘟疫所污染，这场瘟疫扭曲并腐蚀了其范围内的所有生命。这种恶臭的传染源于现在居住在那里的生物的精华。英雄，把这个神圣的小瓶给你。从受困扰的居民那里收集剧毒精华，并使用小瓶的净化能力来清洁林地，恢复土地的和平与活力。","Limitzero"},
[18029] = {"压制烂苔巨魔","\n烂苔巨魔，曾经是一个和谐的部落，现在已经屈服于一种黑暗的影响，这种影响驱使他们走向侵略和恶毒。烂苔斥候在周边徘徊，被感染的烂苔巨魔传播黑暗的痛苦，暗影猎手将黑暗与他们的仪式融为一体，在这片土地上投下阴影。英雄，需要你的力量。对抗这些烂苔巨魔并平息他们的起义，以防止对该地区及其居民造成进一步伤害。","Limitzero"},
[18030] = {"瘟疫掠食者成灾","\n","Limitzero"},
[18031] = {"解除围困","\n","Limitzero"},
[18033] = {"通缉：扎尔奈","\n","Limitzero"},
[18034] = {"横扫血色：魔法与力量","\n","Limitzero"},
[18035] = {"对提尔之手的信仰插旗","\n提尔之手，血色十字军狂热的堡垒，顽强地伫立着，其大教堂代表了他们被误导的热情。为了挑战他们的统治并发出明确的抵抗信息，我们制作了一面体现这片土地真正精神的旗帜。英雄，你的任务不仅仅是把这面旗帜放在大教堂外，还要保护它不被任何人看到。通过这样做，我们打击了他们信仰的核心，激发被他们压迫的人们的希望。","Limitzero"},
[18036] = {"干掉血色精英","\n血色十字军的力量不仅在于他们的人数，还在于他们精英的能力。血色禁卫队，他们事业的强大守护者；血色助祭，充满狂热的精神导师；还有血色法师，狂热的奥术大师。这些数字代表了他们秩序的支柱。英雄，为了在这些动荡的土地上实现和平，必须对抗这些精英，消除他们的威胁。冒险进入他们领域的核心，打破他们统治的枷锁。","Limitzero"},
[18037] = {"象征性的尝试","\n血色十字军在他们不屈不挠的狂热中，带有代表他们的秩序和事业的标志。这些标志通常由他们的成员在提尔之手中佩戴，不仅是忠诚的徽章，还承载着对他们的行动至关重要的信息和计划。通过收集这些标志，我们可以分析他们的策略并占据上风。英雄，冒险进入提尔之手的心脏，取回这些血色徽章。他们的秘密将是我们瓦解他们努力的关键。","Limitzero"},
[18038] = {"通缉：狂热者法兰西娜","\n","Limitzero"},
[18039] = {"压制考林的腐败","\n","Limitzero"},
[18040] = {"消除海洋和陆地的涌动","\n","Limitzero"},
[18041] = {"净化真菌谷","\n真菌谷","Limitzero"},
[18042] = {"被盗命运的回响","\n考林路口和真菌谷周围的土地低声诉说着被偷走的灵魂和大自然的痛苦。考林用他的黑魔法困住了无数的灵魂，他们的本质漫无目的地漂浮着，等待着释放。与此同时，真菌谷里到处都是真菌瘟疫，这让人想起这片土地的疾病。英雄，你有责任找回这些被偷走的灵魂并收集真菌瘟疫。通过这样做，我们可以研究它们，找到一种治愈瘟疫的方法，并释放被考林的邪恶所困住的灵魂。","Limitzero"},
[18043] = {"通缉：荒凉的卡萨文","\n英雄，邪恶的死灵法师荒凉的卡萨文出现在真菌谷，唤醒死者的灵魂，以加强天灾军团对该地区的控制。他的黑暗魔法传播疾病和痛苦，而他的亡灵爪牙攻击所有穿过他们的道路。我恳求你，勇敢的英雄，猎杀这个魔鬼，结束他的恐怖统治。冒险进入山谷，面对卡萨文。","Limitzero"},
[18044] = {"奎尔林斯的骚乱","\n奎尔林斯小屋位于东瘟疫之地的北部，曾经是精灵文明的灯塔。它的居民，主要是樵夫、游骑兵和开拓者，和谐地生活着，保护着精灵领地的边界。然而，最近，一种奇怪的敌意在他们心中扎根。他们对外人的侵略威胁着我们在瘟疫地建立的脆弱和平。英雄，前往奎尔林斯小屋，平息这些精灵的侵略，这样我们就可以揭开他们突然变化的根源。","Limitzero"},
[18045] = {"奎尔林斯的灭亡","\n","Limitzero"},
[18046] = {"该死的饥饿","\n瘟疫之地曾经是一个郁郁葱葱的地区，现在是一片噩梦和悲伤的土地。在这些被诅咒的土地上游荡的无数可憎之物中，有缝合恐怖，黑暗巫术的创造，贪婪的食人魔，以及诅咒法师，挥舞着扭曲魔法的被诅咒灵魂。他们对生者无休止的饥饿威胁着我们设法建立的少数避难所。英雄，我们必须确保这些避风港的安全。冒险进入瘟疫之心，平息这些该死的生物的饥饿。","Limitzero"},
[18047] = {"怪异宝藏","\n在天灾肆虐之后，这片土地上许多宝藏和文物都消失了，现在落入了游走在瘟疫之地的邪恶生物手中。精灵饰品是曾经伟大文明的遗迹，墓穴布上的铭文可能是了解亡灵的关键，而瘟疫等离子体蕴含着强大的能量，我们的学者们渴望研究。英雄，当你面对这片土地上的可憎之物时，请留意这些物品。找回它们对于了解和对抗徘徊在这里的黑暗力量至关重要。","Limitzero"},
[18048] = {"争论焦点","\n如今，西瘟疫之地到处都是亡灵的骸骨，他们被诅咒永远被天灾军团奴役。这些可憎之物——骷髅剥皮者、食尸鬼和骷髅巫师——时刻提醒着人们这片土地上发生的悲剧，以及那些被剥夺了永恒安息的灵魂。我们必须让他们再次安息。英雄，我们需要你的勇气。穿越瘟疫之地，让这些不安的灵魂安息，确保他们不会复活来折磨活人。","Limitzero"},
[18049] = {"安多哈尔驱魔","\n","Limitzero"},
[18050] = {"躁动不安","\n安多哈尔废墟是一个被诅咒的地方，是被天灾军团污染的土地。在这座曾经伟大的城市的残垣断壁中，不安分的亡灵继续肆虐，使恢复或复兴的希望化为泡影。无魂的食尸鬼、骷髅行刑者和骷髅侍僧是造成持续破坏的罪魁祸首。英雄，我们需要你面对这些恶毒的生物，结束他们的恐怖统治。只有这样，我们才有希望夺回安多哈尔，给饱受折磨的灵魂带来安宁。","Limitzero"},
[18051] = {"堕落碎片","\n安多哈尔废墟不仅是天灾军团威力的见证，也是无数曾经将这里视为家园的亡灵的墓地。这些散落在废墟中的白骨碎片是阵亡者的遗骸，是天灾军团愤怒中失去生命的象征。收集这些碎片不仅有助于我们了解破坏的严重程度，也是一种尊重和纪念的姿态。英雄，我们恳求您找回这些碎片，以便我们向阵亡者致敬，并以此洗清安多哈尔令人难以忘怀的过去。","Limitzero"},
[18052] = {"通缉：冷酷的阿科扎尔","\n英雄，死灵法师冰冷的阿科扎尔出现在安多哈尔废墟中，召唤了大批亡灵。他的冰冻魔法只会带来死亡和悲伤，增强天灾的力量。我恳求你，勇敢的勇士，猎杀这个怪物，结束他的恐怖统治。","Limitzero"},
[18053] = {"寒冷与腐烂","\n西瘟疫之地的灵魂漫无目的地游荡，陷入痛苦和折磨之中。他们被束缚在骷髅的躯体中，无法获得来世的安宁。随着黑暗继续笼罩这片土地，阵亡士兵被困的灵魂变得更加焦躁不安。英雄，我们的职责就是给予他们迫切寻求的喘息机会。使用这张以太之网，收集迷失者的灵魂，并将他们带到我身边。这样做，你不仅可以将他们从无尽的痛苦中解救出来，还可以打击那些试图让这片土地永远处于黑暗中的势力。","Limitzero"},
[18054] = {"绝望的回响","\n","Limitzero"},
[18055] = {"不死的威胁","\n西瘟疫之地被巫妖王的邪恶力量所污染，成为噩梦般的亡灵的家园，它们继续在每一个角落徘徊。腐烂的尸体、枯萎的僵尸和骷髅恐怖分子是曾经生活在这片土地上的士兵和居民留下的亡灵。这些可怜的灵魂现在变成了怪物，在不断的折磨中徘徊，对任何经过它们道路的生物都构成了迫在眉睫的威胁。英雄，你的职责很明确。冒险进入这片诅咒之地的中心，消灭这些生物。这是恢复和平的唯一方法，也是确保那些敢于踏足此地的人安全的唯一方法。","Limitzero"},
[18056] = {"粘液化和准备战斗","\n哭泣洞穴曾经是一处静谧的沉思之地，自然风光秀丽，如今却散发着绝望和腐朽的气息。这种转变是这里充斥的软泥怪和黏液怪造成的，它们都是西瘟疫之地仍然存在的瘟疫的产物。其中，吞噬软泥怪、腐烂巨兽和邪恶黏液怪是最强大的，它们留下了腐化的痕迹，危及我们试图恢复的脆弱平衡。英雄，你的任务是进入洞穴，将这些令人厌恶的实体赶走。净化洞穴，让大自然的治愈之手再次发挥作用。","Limitzero"},
[18057] = {"通缉：黑暗凯斯雷冯","\n英雄，邪恶的死灵法师黑暗凯斯雷文出现在被诅咒的村庄 Gahrron's Withering。他的邪恶魔法召唤出大批阴影，祸害大地并攻击所有生物。我恳求你，勇敢的勇士，追捕这个恶棍，在他邪恶蔓延之前将其消灭。前往 Gahrron's Withering，抵抗他的黑暗力量，杀死他，结束他的黑暗统治。","Limitzero"},
[18058] = {"木材与战术：血色先锋","\n血色十字军仍然是西瘟疫之地所有寻求和平的人的眼中钉。特别是他们的伐木工和骑士已经建立了统治地位，无情地砍伐神圣的森林，并向他们遇到的任何人灌输他们的错误信仰。有报道称，这些人随身携带特殊的血色令牌，象征着他们的地位和对事业的承诺。英雄，你的任务是双重的：减少这些顽固敌人的数量，并夺回这些令牌作为他们力量减弱的证明。只有削弱他们的影响力，我们才能希望在这片饱受折磨的土地上看到一丝和平。","Limitzero"},
[18059] = {"血色冲突和塔楼倒塌","\n英雄，瘟疫之地曾经是神圣的土地，如今却充斥着血色十字军的恶毒成员。这些狂热分子盲目地追随消灭的目标，对任何他们认为被污染的人毫不留情。尤其是他们的巫师，他们从黑暗源头汲取力量，并威胁要用他们的奥术力量增强他们的军队。虽然我们削弱了他们的人数，但该地区有一座战略塔，他们声称它是了望点。我们必须确保从他们的控制下夺回它。将我们的旗帜插在塔顶，宣告他们在这里的统治即将结束。","Limitzero"},
[18060] = {"瓦解血色部队","\n壁炉谷曾经是希望和繁荣的灯塔，如今却成了血色十字军误入歧途的狂热堡垒。这座昔日的贵族之城已被他们对新世界的狂热和野蛮幻想所玷污。工人们每天都在加强防御，而圣骑士则在街道上巡逻，确保无人反抗他们的统治。哨兵们站岗放哨，观察并等待任何抵抗的迹象。英雄，是时候削弱他们对壁炉谷的控制，并发出一个明确的信息：他们的暴政不会持续下去。","Limitzero"},
[18061] = {"壁炉谷收割","\n壁炉谷曾经是瘟疫之地的希望灯塔，如今却被狂热的血色十字军所腐蚀。这些误入歧途的灵魂在他们扭曲的使命中夺走了许多人​​的生命。必须扭转局势，让他们知道他们的恐怖统治现在就结束了。英雄，在与他们交战时，收集血色十字军狂热分子的头骨。让它成为他们命运的见证，并警告任何敢于追随他们道路的人。","Limitzero"},
[18062] = {"通缉：狂热者安瑟姆","\n英雄，狂热的圣骑士狂热者安瑟姆从壁炉谷率领血色十字军进行杀戮。他的正义之怒只留下死亡和毁灭，他下令消灭所有非信徒。我恳求你，勇士，潜入壁炉谷，结束安瑟姆的残酷狂热。","Limitzero"},
[18063] = {"抹黑他们","\n拉卡利油沼一直是安戈洛环形山的神秘部分。最近，这些坑变得比平时更加​​活跃，不断涌现出奇怪的焦油生物，它们正在侵占周围的领土。这些生物由坑本身的精华形成，威胁着附近脆弱的生态系统。作为这片古老土地上的英雄，你的职责很明确：你必须冒险前往拉拉卡利油沼，镇压新出现的威胁。制止这些焦油怪物，确保安戈洛居民的安全。","Limitzero"},
[18064] = {"安戈洛混合与匹配","\n安戈洛环形山是一片生机勃勃、充满独特能量和无数谜团的土地。一些当地居民和探险家都曾谈到这片土地上某些天然材料之间的协同作用。他们相信，拉卡利焦油坑的焦油、凶猛的血瓣花植物的叶子和安戈洛大猩猩坚韧的皮毛可以结合起来，产生神秘甚至强大的效果。我们需要一位勇敢的人来收集这些材料以供进一步研究。勇者，站出来收集这些物品，这样我们就可以解开安戈洛的另一个谜团。","Limitzero"},
[18065] = {"猩猩战争","\n真菌岩的猩猩变得越来越具有攻击性，对那些想要了解安戈洛环形山之谜的探险者和研究人员构成了威胁。它们突然的攻击性不仅危及我们的行动，还扰乱了这片史前土地的微妙平衡。英雄，去真菌岩冒险，减少它们的数量。我们必须确保那些进入环形山的冒险者的安全，并恢复这个神圣之地的平衡。","Limitzero"},
[18066] = {"棘手的困境","\n安戈洛环形山的植物一直既奇妙又危险。最近，血瓣花植物生物变得更加具有攻击性，它们侵占了道路并恐吓旅行者。这些曾经温顺的生物现在一见到就发起攻击，使得任何穿越安戈洛的旅程都变得危险重重。我们不能让它们占领环形山。英雄，你必须冒险进入它们的领地中心并削弱它们的数量。","Limitzero"},
[18067] = {"通缉：不稳定的能量水晶","\n安戈洛的大多数的能量水晶都是无害的，只能为附近的水晶塔提供能量。然而，其中一颗似乎吸收了比应有的更多的能量，它的能量一直在向周围扩散，将靠近的人分解。这颗水晶的能量似乎在不断增长，我们担心如果不加以控制，它会摧毁附近的区域。我们需要一个有力量承受它力量的人，在它达到那个程度之前摧毁它。","Limitzero"},
[18068] = {"蹂躏暴掠龙","\n在安戈洛环形山杂草丛生的丛林深处，暴掠龙以其凶猛的气势占据了主导地位。毒皮暴掠龙拥有致命的毒液，狡猾的暴掠龙猎人对试图揭开这片土地之谜的冒险者和研究人员构成了巨大的威胁。随着袭击报告的增加，很明显它们每天都在变得更加大胆。英雄，我们必须采取行动，否则它们的数量会变得过于强大，并会冲出它们的领地。","Limitzero"},
[18069] = {"扑灭安戈洛的烈焰","\n安戈洛环形山以其茂盛的绿色植物和奇异的生物而闻名，同时也拥有在陆地上游荡的火元素的强烈热量。最近，灼热元素和活火一直在肆虐，使土地燃烧并危及居民。这种情况不能再继续了。英雄，我们需要你的专业知识。冒险进入火热的地区并平息这些火热的敌人。让我们确保安戈洛仍然是自然的天堂，而不是燃烧的地狱。","Limitzero"},
[18070] = {"顶级掠食者","\n在安戈洛环形山的中心，自然界一直保持着平衡。然而，最近，某些捕食者的数量不断增加，破坏了这种微妙的平衡。双龙、暴掠龙和它们的敏捷同类暴掠龙奔跑者现在对其他生物甚至像你这样的旅行者构成了相当大的威胁。作为平衡的捍卫者，英雄，我们需要你的技能。减少它们的数量，让安戈洛恢复和平。","Limitzero"},
[18071] = {"安戈洛的精华：利爪、核心与心脏","\n有了这些基本成分，我们距离理解安戈洛生命错综复杂的平衡又近了一步。你们的努力确保了仪式能够顺利进行，对此我们深表感谢。通过理解和尊重这些生物的力量，我们的目标是保护和保存安戈洛环形山的奇迹。你的名字将被铭刻在古老的圣歌中，英雄。","Limitzero"},
[18072] = {"通缉：因瑟拉塔斯","\n英雄，可怕的火元素怪因瑟拉塔斯在火羽岭徘徊，喷出的火焰伤痕累累。它灼热的魔法将所有生命焚烧殆尽，而低等元素怪则听从它的命令蜂拥而至。我恳求你，勇敢的勇士，追捕这个地狱暴君。前往山脊，抵挡因瑟拉塔斯的烈焰怒火，并在它炽热的攻击吞噬安戈洛之前将其杀死。","Limitzero"},
[18073] = {"格里什虫巢浩劫","\n在安戈洛环形山深处，格里什异种虫形成了一个庞大的巢穴，每种异种虫在其社会中都扮演着独特的角色。然而，最近，它们的攻击性行为有所增加，危及附近的栖息地和旅行者。英雄，我们需要你进入格里什虫巢并减少它们的数量。通过瞄准劫掠者、工蝎和异种蝎，我们希望暂时阻止它们的侵略性扩张。","Limitzero"},
[18074] = {"天空恐怖与远古掠食者","\n英雄，安戈洛环形山的和谐平衡再次受到威胁。狂暴的翼手龙翱翔在空中，肆意破坏，以较小的生物为目标，让许多人心生恐惧。在地面上，史前时代的残存的长老双龙正在宣称它们对较小的生物的统治，挑战自然秩序。我们请求你介入，通过对付这些强大的敌人来恢复平衡。","Limitzero"},
[18075] = {"安戈洛热气腾腾","\n安戈洛火山著名的温泉确实是艾泽拉斯的自然奇观。被加热的水蕴藏着来自地球深处的强大元素能量。它们通常处于休眠状态，但最近这些力量已经涌动，导致泉水沸腾翻滚。冒险家，我有一项重要任务要交给你。前往温泉，读取它们当前的元素活动。这种对自然平衡的干扰让我很担心。在元素力量的上升引发剧烈的事情之前，温泉必须平静下来。使用此热异常探测器监测温泉周围的温度、气体成分和神秘波动。","Limitzero"},
[18076] = {"安戈洛的主要产物","\n在安戈洛环形山中心，动植物群以原始的能量奔腾。要真正了解这个地方的本质，必须收集其生命的有形象征。从格里什虫群坚硬的外壳到早已死亡的爬行动物的古老遗骸，再到活着的剑龙厚皮，收集这些将让我们深入了解驱使安戈洛的生命力。英雄，你能把这些东西带给我吗？","Limitzero"},
[18077] = {"通缉：瓦沙克大王","\n英雄，被称为瓦沙克大王的巨大魔暴龙仅凭蛮力就统治着安戈洛环形山。这种可怕的野兽会袭击所有经过它的人，而较小的魔暴龙则会服从它的野蛮命令。我恳求你，勇敢的勇士，追捕这一威胁。","Limitzero"},
[18078] = {"削弱食人魔","\n巨槌石是燃烧平原上的一座高耸堡垒，长期以来一直是火腹食人魔的避难所。这群野兽由火腹食人魔和他们更强大的野蛮兄弟和阴暗的食人魔法师组成，他们声称对巨槌石拥有统治权，并对附近的定居点和毫无戒心的旅行者构成越来越大的威胁。他们对黑暗魔法日益增长的亲和力和日益增强的力量不容忽视。英雄，我们必须直面这一局面。深入巨槌石，减少他们的数量。我们必须迅速采取行动，确保他们不会进一步巩固他们的据点。","Limitzero"},
[18079] = {"镇压龙类","\n英雄，一个令人不安的发展正在进行中。黑龙氏族加强了其在燃烧平原内的有生力量。有报道称，黑色龙人、黑色龙裔和黑色幼龙大量涌入该地区，他们的意图从来都不是纯粹的。从历史上看，在这些龙人聚集的地方，黑龙氏族正在策划一些可怕的事情。我们必须在他们的计划实现之前斩断蛇头。与这些龙人交战，消灭他们的数量。我们负担不起黑龙氏族在这些地区站稳脚跟。","Limitzero"},
[18080] = {"索瑞森遗产的阴影","\n","Limitzero"},
[18081] = {"烧毁的收藏品","\n燃烧的草原是一片富含过去战斗遗迹的土地。虽然大多数人认为它们只是纪念品，但我们的研究人员认为这些文物讲述了这片土地的故事，讲述了食人魔、龙和黑铁矮人之间的冲突。取回这些物品，这样我们就可以拼凑出这片危险土地的更清晰的历史。","Limitzero"},
[18082] = {"通缉：维卡什","\n","Limitzero"},
[18083] = {"击退黑石猛攻","\n","Limitzero"},
[18084] = {"控制火鳞的威胁","\n","Limitzero"},
[18085] = {"要塞决战","\n","Limitzero"},
[18086] = {"熔岩、生命和遗物","\n","Limitzero"},
[18087] = {"通缉：暗影燃烧者德拉加","\n","Limitzero"},
[18089] = {"亚考罗克的信徒","\n","Limitzero"},
[18090] = {"雷加什的阴影","\n","Limitzero"},
[18091] = {"精灵入侵","\n","Limitzero"},
[18092] = {"艾萨拉的回响","\n","Limitzero"},
[18093] = {"通缉：阿卡拉什","\n","Limitzero"},
[18094] = {"驯服恶鞭","\n英雄，令人不安的浪潮席卷了艾萨拉的海岸，传来恶鞭纳迦的攻击性动向。恶鞭纳迦的战斗大师和女巫们一直在集结军队，似乎准备向内陆发起大规模进攻。我们绝不能让他们在艾萨拉站稳脚跟。潜入深海，对抗这些蛇形敌人，确保海岸不受他们的控制。","Limitzero"},
[18095] = {"奥术干扰","\n","Limitzero"},
[18096] = {"来自悬崖的回响","\n","Limitzero"},
[18097] = {"威胁的妙处","\n","Limitzero"},
[18098] = {"通缉：瓦尔克萨斯","\n","Limitzero"},
[18099] = {"搅动沙漠","\n","Limitzero"},
[18100] = {"风中低语","\n","Limitzero"},
[18101] = {"暮光的骚乱","\n","Limitzero"},
[18102] = {"沙漠的灾难","\n","Limitzero"},
[18103] = {"通缉：雷克西狄斯","\n","Limitzero"},
[18104] = {"撕裂虫巢","\n","Limitzero"},
[18105] = {"暮光之锤的阴影","\n","Limitzero"},
[18106] = {"沙漠掠食者","\n","Limitzero"},
[18107] = {"沙漠的秘密","\n","Limitzero"},
[18108] = {"通缉：高阶女祭司阿齐尔","\n","Limitzero"},
[18109] = {"压制雷戈虫巢","\n英雄，雷戈虫巢的异种虫变得越来越咄咄逼人，他们的扩张威胁着希利苏斯的平衡。其中，雷戈喷火者、雷戈主宰和雷戈制奴者尤其麻烦，他们领导和协调着他们的巢穴活动。我们必须打击这些关键目标，以阻止异种虫的前进，维护沙漠脆弱的平衡。","Limitzero"},
[18110] = {"希利苏斯的黄昏","\n","Limitzero"},
[18111] = {"从痛苦中解脱","\n","Limitzero"},
[18112] = {"恢复元素","\n","Limitzero"},
[18113] = {"通缉：议长库兰","\n英雄，被称为议长库兰的其拉先知居住在雷戈虫巢，为异种虫群提供力量。他的邪恶魔法使他们能够进行无情的攻击，而他的声音则召集了他们的虫群军团。我恳求你，勇敢的勇士，潜入巢穴，让议长闭嘴。","Limitzero"},
[18114] = {"通缉：腐蚀者萨斯里瓦尔","\n英雄，邪恶的亡灵巫师腐蚀者萨斯里瓦尔在病木林深处练习黑魔法，培养出大批亡灵。他的邪恶力量传播疾病和腐烂，扭曲环境。我恳求你，勇敢的勇士，追捕这个恶棍。进入病木林的腐烂森林，找到巫师的巢穴，杀死他，这样他的邪恶就不会再蔓延了。","Limitzero"},
