[50015] = {"遏制邪恶：入侵点大灾变 （高风险）","\n消灭8个灾难监工和6个魔能机甲斥候","Limitzero"},
[50016] = {"遏制邪恶：伊克利普森农场 （高风险）","\n消灭5个疯狂的巨人","Limitzero"},
[50017] = {"遏制邪恶：征服之路 （高风险）","\n消灭8个戈多克之子和4个伊利达雷监视者","Limitzero"},
[50018] = {"遏制邪恶：阿卡隆斯山脊 （高风险）","\n消灭6个法兰伦巨人。","Limitzero"},
[50019] = {"遏制邪恶：虚空石 （高风险）","\n消灭12个法兰伦击碎者。","Limitzero"},
[50020] = {"遏制邪恶：坠星山 （高风险）","\n消灭20个暴怒的巨人。","Limitzero"},
[50021] = {"遏制邪恶：铸魔营地 （高风险）","\n摧毁8个恶魔卫士军团士兵和8个莫尔葛工程师。","Limitzero"},
[50022] = {"遏制邪恶：格鲁尔巢穴外 （高风险）","\n消灭22个刀塔兽人。","Limitzero"},
[50023] = {"遏制邪恶：暮光山脊 （高风险）","\n消灭5个死影主宰和6个死影术士。","Limitzero"},
[50024] = {"人口控制：破碎的骷髅 (高风险)","\n前往白骨荒野，消灭30具破碎的骷髅。","Limitzero"},
