[77852] = {"钢铁决心!","\n进入大熔炉后，只有两种方法可以离开。您能杀死目标并逃脱吗？ 名黑铁工头、7 名黑铁奴隶贩子和10 名黑铁了哨兵。亡的情况下完成。","Limitzero"},
[77853] = {"我可以狩猎更多哈扎里?","\n消灭10只哈扎里群居蝎、哈扎里异种蝎和哈扎里沙行者。","Limitzero"},
