[77856] = {"经批准的狩猎：灼热峡谷!","\n消灭10个南海重型作战傀儡、熔岩元素、炽热元素和灼热熔岩蜘蛛。","Limitzero"},
[77865] = {"经批准的狩猎：瘟疫之地!","\n消灭10只生病的灰熊、天灾潜伏者、天灾蝙蝠和狂怒的天灾犬。","Limitzero"},
[77866] = {"经批准的狩猎：冬泉谷!","\n消灭10只冬泉巨枭、冰风破坏者、霜刃雌豹和5只游荡的冰蓟雪人。","Limitzero"},
