[81248] = {"深入英雄地下城","\n完成英雄地下城，前往任意主城的公告板。","Limitzero"},
[81249] = {"深入史诗地下城","\n完成史诗地下城，前往任意主城的公告板。","Limitzero"},
[81250] = {"主城围攻：暴风城之战","\n在艾尔文森林的青山中，坐落着人类国家暴风城!攻击暴风城，杀死人类的现任首领伯瓦尔・弗塔根公爵!",""},
[81251] = {"主城围攻：铁炉堡之战","\n在丹莫罗冰霜覆盖的深山中，住着矮人。他们在地表下的城市叫做铁炉堡。围攻铁炉堡并杀死矮人领袖麦格尼・铜须!","Limitzero"},
[81252] = {"主城围攻：达纳苏斯之战","\n在卡利姆多的北极西面，矗立着世界之树泰达希尔。隐藏在树冠中的达纳苏斯是暗夜精灵的家园。爬上泰达希尔，进入达纳苏斯，杀死暗夜精灵首领泰兰德・语风!","Limitzero"},
[81253] = {"主城围攻：奥格瑞玛之战","\n在现在被称为杜隆塔尔的红色沙漠中，兽人建造了一座强大的城市。围攻奥格瑞玛，拿下兽人首领索尔。","Limitzero"},
[81254] = {"主城围攻：幽暗城之战","\n洛丹伦废墟深处有一座幽暗城。这里是摆脱了巫妖王影响的亡灵的家园。攻击幽暗城并杀死亡灵首领希尔瓦娜斯・风行者!","Limitzero"},
[81255] = {"主城围攻：雷霆崖之战","\n在莫高雷山谷最陡峭的石柱顶端，是牛头人建造家园的地方。雷霆崖是一座与众不同的城市。烧毁它并杀死牛头人的首领凯恩・血蹄。","Limitzero"},
[81260] = {"战斗号令：战场","\n赢得任意战场比赛并回到公告板处领取奖励。","Limitzero"},
