[81297] = {"时空漫游地下城：生态船","\n净化生态船，消灭迁跃扭木。","Limitzero"},
[81298] = {"时空漫游地下城：禁魔监狱","\n保护禁魔监狱，消灭预言者斯克瑞斯。","Limitzero"},
[81299] = {"时空漫游地下城：奴隶围栏","\n解放奴隶围栏，消灭夸格米拉。","Limitzero"},
[81300] = {"时空漫游地下城：幽暗沼泽","\n征服幽暗沼泽，消灭黑色阔步者。","Limitzero"},
[81301] = {"时空漫游地下城：蒸汽地窟","\n关闭蒸汽地窟并消灭督军卡利瑟里斯。","Limitzero"},
[81302] = {"时空漫游地下城：地狱火堡垒","\n征服地狱火城墙，消灭传令官瓦兹德。","Limitzero"},
[81303] = {"时空漫游地下城：鲜血熔炉","\n征服鲜血熔炉，消灭击碎者克里丹。","Limitzero"},
[81304] = {"时空漫游地下城：破碎大厅","\n征服破碎大厅并消灭酋长卡加斯・刃拳。","Limitzero"},
[81305] = {"时空漫游地下城：旧希尔斯布莱德丘陵","\n保护时间秩序，消灭时空猎手。","Limitzero"},
[81306] = {"时空漫游地下城：黑色沼泽","\n保护时间秩序，消灭埃欧努斯。","Limitzero"},
[81307] = {"时空漫游团队副本：卡拉赞","\n将玛克扎尔王子驱逐出卡拉赞!","Limitzero"},
[81308] = {"时空漫游团队副本：祖阿曼","\n阿曼尼森林巨魔因其大胆的团队而被称为昭著。祖尔金是负责团队奎尔萨拉斯的督军，尽管巨魔已被高等精灵蹂躏殆尽。他又在祖阿曼建立了自己的军队。别搞错了。。。如果祖尔金开始团队，那将是毁灭性的杀了祖尔金。没有了督军，巨魔军队将不再是威胁。","Limitzero"},
[81309] = {"时空漫游团队副本：格鲁尔的巢穴","\n消灭屠龙者格鲁尔。","Limitzero"},
[81310] = {"时空漫游团队副本：玛瑟里顿的巢穴","\n洒尽玛瑟里顿的鲜血。","Limitzero"},
[81311] = {"时空漫游团队副本：毒蛇神殿","\n把瓦丝琪<盘牙女王>晾干。","Limitzero"},
[81312] = {"时空漫游团队副本：暴风城","\n征服凯尔萨斯。","Limitzero"},
[81313] = {"时空漫游团队副本：海加尔山之战","\n把阿克蒙德留在过去。","Limitzero"},
[81314] = {"时空漫游团队副本：黑暗神殿","\n消灭伊利丹","Limitzero"},
[81315] = {"时空漫游团队副本：太阳井高地","\n千百年来，太阳井为高阶精灵的强大魔法提供了燃料。燃烧军团将一切都献给了这个古老的力量源泉，因为有了它，他们就有办法召集出他们的指挥官基尔杰顿。如果基尔加丹上场，我们必死无疑。但燃烧军团也给了我们在这场战争中给予决定性一击的机会。就是它了，英雄。打败燃烧军团。","Limitzero"},
