[91001] = {"遏制邪恶：门纳尔湖","\n从艾萨拉门纳尔湖，带着30个蓝色龙爪作为你的行为证明。","Limitzero"},
[91002] = {"遏制邪恶：奥卡兹岛","\n尘泥沼泽的奥卡兹岛上的家，杀死娜迦，然后带着30颗珍珠回来。","Limitzero"},
[91003] = {"遏制邪恶：梦境之树","\n从菲拉斯的梦境之树带回40个梦境鳞片。","Limitzero"},
[91004] = {"遏制邪恶：加德米尔湖","\n从菲拉斯的加德米尔湖携带10个永恒梦境鳞片回来。","Limitzero"},
[91005] = {"遏制邪恶：奥奈罗斯","\n从菲拉斯的奥奈罗斯带回40个奥奈罗斯鳞片。","Limitzero"},
[91006] = {"遏制邪恶：恐怖岛","\n从菲拉斯恐怖岛每种奇美洛克带四只翅膀回来。","Limitzero"},
[91007] = {"遏制邪恶：暗语峡谷","\n在冬泉谷应对暗语峡谷中的恶魔威胁。","Limitzero"},
[91008] = {"遏制邪恶：霜语峡谷","\n从冬泉谷的霜语峡谷带回15个霜槌碎片和4个霜槌魂精。","Limitzero"},
[91009] = {"遏制邪恶：麦索瑞尔","\n从冬泉谷的麦索瑞尔带回鳞片。","Limitzero"},
[91010] = {"遏制邪恶：腐烂之痕","\n东瘟疫之地腐烂之痕的亡灵",""},
[91011] = {"遏制邪恶：提尔之手","\n东瘟疫之地提尔之手的血色十字军",""},
[91012] = {"遏制邪恶：赎罪岛","\n希尔斯布莱德丘陵的赎罪岛","Limitzero"},
[91014] = {"遏制邪恶：龙喉大门","\n从龙喉大门带回30块皇家红色龙鳞。","Limitzero"},
[100107] = {"锻造之怒","\n","Limitzero"},
[100108] = {"锻造之怒","\n进入虚空风暴的中心地带，与恐怖卫兵、天罚使者和天罚领主展开战斗!","Limitzero"},
[170001] = {"主城围攻：铁炉堡之战","\n在丹莫罗冰霜覆盖的深山中，住着矮人。他们在地表下的城市叫做铁炉堡。围攻铁炉堡并杀死矮人领袖麦格尼・铜须!","Limitzero"},
[170002] = {"主城围攻：达纳苏斯之战","\n在卡利姆多的北极西面，矗立着世界之树泰达希尔。隐藏在树冠中的达纳苏斯是暗夜精灵的家园。爬上泰达希尔，进入达纳苏斯，杀死暗夜精灵首领泰兰德・语风!","Limitzero"},
[170003] = {"主城围攻：埃索达之战","\n在埃索达消灭先知维伦。","Limitzero"},
[170004] = {"主城围攻：奥格瑞玛之战","\n在现在被称为杜隆塔尔的红色沙漠中，兽人建造了一座强大的城市。围攻奥格瑞玛，拿下兽人首领索尔。","Limitzero"},
[170005] = {"主城围攻：幽暗城之战","\n洛丹伦废墟深处有一座幽暗城。这里是摆脱了巫妖王影响的亡灵的家园。攻击幽暗城并杀死亡灵首领希尔瓦娜斯・风行者!","Limitzero"},
[170006] = {"主城围攻：雷霆崖之战","\n在莫高雷山谷最陡峭的石柱顶端，是牛头人建造家园的地方。雷霆崖是一座与众不同的城市。烧毁它并杀死牛头人的首领凯恩・血蹄。","Limitzero"},
[170007] = {"主城围攻：银月城之战","\n在银月城消灭哈杜伦・明翼<游侠将军>，洛瑟玛・塞隆和大法师罗曼斯","Limitzero"},
[170010] = {"艾泽拉斯的威胁：瑟提斯","\n消灭希利苏斯的瑟提斯","Limitzero"},
[170011] = {"艾泽拉斯的威胁：卡扎克","\n消灭诅咒之地的卡扎克","Limitzero"},
[170012] = {"艾泽拉斯的威胁：艾索雷葛斯","\n消灭艾萨拉的艾索雷葛斯","Limitzero"},
[170013] = {"艾泽拉斯的威胁：莱索恩","\n消灭辛特兰的莱索恩","Limitzero"},
[170014] = {"艾泽拉斯的威胁：艾莫莉丝","\n消灭菲拉斯的艾莫莉丝","Limitzero"},
[170015] = {"艾泽拉斯的威胁：泰拉尔","\n消灭暮色森林的泰拉尔","Limitzero"},
[170016] = {"艾泽拉斯的威胁：伊森德雷","\n消灭灰谷的伊森德雷","Limitzero"},
[171000] = {"主城保卫战：保卫你的主城","\n保卫你的主城","Limitzero"},
[171004] = {"主城保卫战：保卫你的主城","\n保卫你的主城","Limitzero"},
[171998] = {"巫妖王日常","\n消灭高风险怪物","Limitzero"},
[171999] = {"巫妖王日常（高风险）","\n消灭高风险怪物","Limitzero"},
[172000] = {"考达拉：保护者","\n在考达拉中击败审讯者卡勒拉斯，塞鲁利恩将军和战争使者戈德拉克<蓝龙军团的领主>，瓦解玛里苟斯对魔网的控制，保护艾泽拉斯的魔法平衡。","Limitzero"},
[172001] = {"考达拉：蓄积的能量","\n在考达拉消灭奥术浮蛇，以防止不受控制的奥术能量破坏魔网的稳定，进一步破坏艾泽拉斯的魔法平衡。","Limitzero"},
[172002] = {"考达拉：看他们倒下","\n在考达拉消灭魔枢观察者，瓦解玛利苟斯对魔网的控制，保护艾泽拉斯的魔法平衡。","Limitzero"},
[172003] = {"考达拉：倾斜的天平","\n在考达拉的深蓝龙族处收集科深蓝龙族鳞片，帮助抵消玛利苟斯对魔网的控制，保护艾泽拉斯的魔法平衡。","Limitzero"},
[172004] = {"考达拉：寒冷搜寻者","\n在考达拉地区寻找并掠夺魔枢龙，强效晶化法力，魔力束缚的远古树皮和地质报告，帮助我们更好地了解正在发挥作用的奥术力量，保护艾泽拉斯的魔法平衡。","Limitzero"},
[172005] = {"喷泉平原：机械大混乱","\n功能失常的机器人占领了喷泉平原，正在造成破坏。我们需要派出英雄消除威胁，确保该地区的安全。","Limitzero"},
[172006] = {"喷泉平原：拦截发明","\n从喷泉平原的菲兹兰克机械侏儒中掠夺奇怪的原理图。","Limitzero"},
[172007] = {"喷泉平原：晶化能源","\n从喷泉平原收集12块油浸盐晶体。","Limitzero"},
[172008] = {"喷泉平原：消灭尼鲁巴尔","\n在喷泉平原消灭尼鲁巴尔喷毒者、尼鲁巴尔战士、尼鲁巴尔坑道虫。","Limitzero"},
[172009] = {"喷泉平原：孵化计划","\n摧毁喷泉平原中尼鲁巴尔蛛卵簇。","Limitzero"},
[172010] = {"塔尔拉玛斯：信息瘟疫","\n在垂死兽穴附近，收集天灾猛犸象身上的天灾肉，以及天灾猛犸人身上的天灾血样。","Limitzero"},
[172011] = {"塔尔拉玛斯：净化塔尔拉玛斯","\n在塔尔拉玛斯中消灭白骨战士、塔尔拉玛斯憎恶和生疮的食尸鬼。","Limitzero"},
[172012] = {"塔尔拉玛斯：亡灵编年史","\n从塔尔拉玛斯和圣城恩其拉收集四本通灵魔法书。","Limitzero"},
[172013] = {"塔尔拉玛斯：消除恩卡拉威胁","\n在圣城恩其拉消灭恩其拉憎恶、恩其拉地穴魔、恩其拉石像鬼和恩其拉食尸鬼。","Limitzero"},
[172014] = {"塔尔拉玛斯：破坏黑暗仪式","\n在塔尔拉玛斯和圣城恩其拉消灭诅咒教派药剂师<诅咒教派>和恩其拉通灵师<诅咒教派>。","Limitzero"},
[172015] = {"犸格莫斯：平息元素风暴","\n分别在艾卓纳斯遗迹，沸腾之池和焦化之丘消灭狂怒的雷暴、沸腾之魂和暴怒的火焰，恢复元素的平衡。","Limitzero"},
[172016] = {"犸格莫斯：元素和谐","\n从艾卓纳斯遗迹，沸腾之池和焦化之丘的元素怪身上收集狂怒元素空气、沸腾元素之水和暴怒元素之火。","Limitzero"},
[172017] = {"犸格莫斯：粉碎犸格莫斯的威胁","\n在犸格莫斯地区击败犸格莫斯碾压者。","Limitzero"},
[172018] = {"犸格莫斯：黑暗中的烛光","\n在犸格莫斯的犸格莫斯萨满祭司和犸格莫斯劫掠者处，收集5个熄灭的蜡烛。","Limitzero"},
[172019] = {"犸格莫斯：施加狩猎","\n在北风苔原的北部区域地区收集10件丢失的物资。","Limitzero"},
[172020] = {"卡斯卡拉：雾中青蛙","\n从洪荒平原的蒸汽蛙处收集5只蒸汽蛙。","Limitzero"},
[172021] = {"卡斯卡拉：咒术师的材料","\n收集克瓦迪尔劫掠者的深海海带，蒸汽鳄鱼人的其他青蛙肉和沼泽驯鹿的驯鹿角，协助制作达拉然法师的特制炖菜。","Limitzero"},
[172022] = {"卡斯卡拉：戈尔洛克威胁","\n在洪荒平原击败游荡鳄鱼人、鼓眼鳄鱼人和蒸汽鳄鱼人。","Limitzero"},
[172023] = {"卡斯卡拉：转化海潮","\n在卡斯卡拉击败15名克瓦迪尔劫掠者。","Limitzero"},
[172024] = {"卡斯卡拉：可怕的一对","\n消除布戈布咕酋长和可怕的赫迦尔的威胁，恢复洪荒平原和卡斯卡拉的和平与和谐。","Limitzero"},
[172025] = {"巫妖王日常","\n消灭低风险怪物","Limitzero"},
[172026] = {"巫妖王日常","\n消灭低风险怪物","Limitzero"},
