[172030] = {"神殿增援 - 红玉巨龙圣地","\n在龙骨荒野的红玉巨龙圣地中击败10个冰冷憎恶。","Limitzero"},
[172031] = {"神殿增援 - 红玉巨龙圣地","\n采集10片血色橡树花瓣。","Limitzero"},
[172032] = {"神殿增援 - 红玉巨龙圣地","\n在红玉巨龙圣地中击败瓦伦哈尔公爵<巫妖王的仆从>、达莉亚、7个冰冷通灵师和7个冰冷恶鬼。","Limitzero"},
[172033] = {"神殿增援 - 红玉巨龙圣地","\n在红玉巨龙圣地击败10只龙骨秃鹰和1只恐怖之爪。","Limitzero"},
[172034] = {"神殿增援 - 红玉巨龙圣地","\n从红玉巨龙圣地的怪物身上收集20块寒冷的白骨碎片。","Limitzero"},
[172035] = {"神殿增援 - 翡翠巨龙圣地","\n从翡翠巨龙圣地的圣地收集10颗翡翠龙泪。","Limitzero"},
[172036] = {"神殿增援 - 翡翠巨龙圣地","\n在翡翠巨龙圣地击败10个翡翠天爪枭。","Limitzero"},
[172037] = {"神殿增援 - 翡翠巨龙圣地","\n从翡翠巨龙圣地中的怪物身上收集15根翡翠羽毛。","Limitzero"},
[172038] = {"加入弗雷 - 新壁炉谷","\n在新壁炉谷的先锋军步兵、先锋军黑鸦祭司、指挥官乔丹，阿比迪斯将军和海军上将巴利・韦斯温处收集20件先锋军的军械。","Limitzero"},
[172039] = {"加入弗雷 - 新壁炉谷","\n在新壁炉谷战胜15个先锋军士兵。","Limitzero"},
[172040] = {"神殿增援 - 黑曜石巨龙圣地","\n从黑曜石巨龙圣地中的冒烟的骷髅，冒烟的构造体和冒烟的恶鬼身上收集10个燃烧的炽热之火。","Limitzero"},
[172041] = {"神殿增援 - 黑曜石巨龙圣地","\n在黑曜石巨龙圣地中破坏10个通灵符石并击败腐烂者洛森<诅咒教派>。","Limitzero"},
[172042] = {"加入弗雷 - 天谴之门","\n在天谴之门安加萨使用燃烧的炽热之火烧掉10个安加萨畸形体。","Limitzero"},
[172043] = {"加入弗雷 - 天谴之门","\n在天谴之门安加萨消灭7个狂乱的石像鬼和3个安加萨通灵领主<诅咒教派>。","Limitzero"},
[172044] = {"加入弗雷 - 天谴之门","\n消灭巨型憎恶，它是潜伏在天谴之门安加萨的巨大骷髅怪物。","Limitzero"},
[172045] = {"神殿增援 - 青铜巨龙圣地","\n在青铜巨龙圣地中击败8个永恒时空破坏者，并在战斗中使用时空之沙样本。","Limitzero"},
[172046] = {"神殿增援 - 青铜巨龙圣地","\n在青铜巨龙圣地收集16个时空之沙样本。","Limitzero"},
[172047] = {"诺森德研究 - 霜之哀伤洞穴","\n从霜之哀伤洞穴的冰雪亡魂身上收集12个死亡使者精华。","Limitzero"},
[172048] = {"诺森德研究 - 黎明之镜","\n从黎明之镜中的冰雪亡魂身上收集12块冰冻钢铁碎片。","Limitzero"},
[172049] = {"加入弗雷 - 血色岗哨","\n在血色哨站消灭10名先锋军石工，10名先锋军士兵和5名先锋军死亡骑士。","Limitzero"},
[172050] = {"加入弗雷 - 与阿努巴尔的战争","\n在冰雾村和纳尔苏深渊的阿努巴尔杀戮者，阿努巴尔教徒，阿努巴尔荒芜兽和阿努巴尔蛛魔领主身上收集30份阿努巴尔毒液。","Limitzero"},
[172051] = {"加入弗雷 - 与阿努巴尔的战争","\n在冰雾村和纳尔苏深渊消灭10个阿努巴尔杀戮者和10个阿努巴尔荒芜兽。","Limitzero"},
[172052] = {"加入弗雷 - 与阿努巴尔的战争","\n在冰雾村和纳尔苏深渊打碎10个阿努巴尔之卵。","Limitzero"},
[172053] = {"加入弗雷 - 与阿努巴尔的战争","\n在纳尔苏深渊收集10个尤格-萨隆的黑血。","Limitzero"},
[172054] = {"加入弗雷 - 与阿努巴尔的战争","\n在纳尔苏深渊击败8个阿努巴尔蛛魔领主。","Limitzero"},
[172055] = {"加入弗雷 - 解除纳克萨玛斯军队的武装","\n在龙骨荒野的天灾攻城锻造师那里收集10个攻城锻造师的炸弹。","Limitzero"},
[172056] = {"加入弗雷 - 解除纳克萨玛斯军队的武装","\n在龙骨荒野中使用攻城锻造师的炸弹引爆10辆天灾战车。","Limitzero"},
