[172170] = {"研究世界古树 - 灰喉堡","\n从灰喉堡分别收集到沃达希尔之泪、沃达希尔之心、沃达希尔之肢、沃达希尔之隘和沃达希尔之根样本。","Limitzero"},
[172171] = {"研究世界古树 - 灰喉堡","\n在灰喉堡打败7个霜爪战士和7个红牙猎人。","Limitzero"},
[172172] = {"研究世界古树 - 灰喉堡","\n在灰喉堡收集10个萨隆邪铁渗液样本。","Limitzero"},
[172173] = {"研究世界古树 - 灰喉堡","\n在灰喉堡击败8个萨隆恐怖软泥和7个熵能软泥怪。","Limitzero"},
[172174] = {"研究世界古树 - 灰喉堡","\n在灰喉堡收集10件战争物资。","Limitzero"},
[172175] = {"加入弗雷 - 丹厄古尔","\n在丹厄古尔击败铁砧<弗雷哈默尔的卫士>。","Limitzero"},
[172176] = {"加入弗雷 - 丹厄古尔","\n在丹厄古尔收集15件暗铁物资。","Limitzero"},
[172177] = {"加入弗雷 - 丹厄古尔","\n在丹厄古尔战胜符文工匠卡索恩和杜拉尔。","Limitzero"},
[172178] = {"加入弗雷 - 丹厄古尔","\n在丹厄古尔打败8个闪电斥候和10个符文作战魔像。","Limitzero"},
[172179] = {"加入弗雷 - 丹厄古尔","\n从丹厄古尔倒下的敌人身上收集10个魔像核心符文。","Limitzero"},
[172180] = {"消灭瘟疫 - 塞布哈拉克","\n在塞布哈拉克战胜6个达卡莱天灾传播者和5个达卡莱药剂师。","Limitzero"},
[172181] = {"消灭瘟疫 - 塞布哈拉克","\n在塞布哈拉克击败15名惊骇的达卡莱战士。","Limitzero"},
[172182] = {"消灭瘟疫 - 塞布哈拉克","\n在塞布哈拉克击败8个天灾亡语者和督军希姆波。","Limitzero"},
[172183] = {"消灭瘟疫 - 塞布哈拉克","\n从塞布哈拉克处收集10达卡莱瘟疫毒素。","Limitzero"},
[172184] = {"消灭瘟疫 - 塞布哈拉克","\n从塞布哈拉克的污秽怪物身上收集30份受污染的汗液。","Limitzero"},
