[177895] = {"时空漫游地下城：死亡矿井","\n进入死亡矿井，消灭艾德温・范克里夫。","Limitzero"},
[177896] = {"时空漫游地下城：诺莫瑞根","\n进入诺莫瑞根消灭机械师瑟玛普拉格。","Limitzero"},
[177897] = {"时空漫游地下城：剃刀沼泽","\n进入剃刀沼泽，消灭卡尔加・刺肋<长者>。","Limitzero"},
[177898] = {"时空漫游地下城：黑暗深渊","\n进入黑暗深渊，消灭阿库麦尔。","Limitzero"},
[177899] = {"时空漫游地下城：血色图书馆","\n进入血色修道院，消灭奥术师杜安。","Limitzero"},
[177900] = {"时空漫游地下城：血色大教堂","\n进入血色修道院，消灭赫洛德<血色十字军勇士>和血色十字军指挥官莫格莱尼。","Limitzero"},
[177901] = {"时空漫游地下城：剃刀高地","\n进入剃刀高地并消灭寒冰之王亚门纳尔。","Limitzero"},
[177902] = {"时空漫游地下城：祖尔法拉克","\n进入祖尔法拉克，消灭乌克兹・沙顶。","Limitzero"},
[177903] = {"时空漫游地下城：玛拉顿","\n进入玛拉顿并消灭瑟莱德丝公主。","Limitzero"},
[177904] = {"时空漫游地下城：奥达曼","\n进入奥达曼，消灭阿扎达斯<远古巨石卫士>。","Limitzero"},
[180133] = {"导师：帮助新玩家","\n通过与新玩家组队并帮助新玩家，可获得导师印记。只有新获得的导师印记才能获得奖励。","Limitzero"},
