[354035] = {"信诺攻势","\n","Limitzero"},
[354036] = {"保卫我们的边界","\n前往图雷姆，削减那里的破碎者和迷失者的数量","Limitzero"},
[354037] = {"疏伐森林","\n","Limitzero"},
[354038] = {"和平献礼","\n图雷姆的破碎者和迷失者早已与光明隔绝。但如果得到怜悯，他们或许还能找到救赎。把这些德莱尼补给品送到帐篷里，代表我们表达希望。这些补给品包括食物，水，药品和一个被光明之光加持的水晶。如果得到热情接待，这可能是我们两国人民之间恢复信任的第一步。但请谨慎行事--并非所有人都欢迎这份礼物。","Limitzero"},
[354039] = {"闪闪发光的追求","\n","Limitzero"},
[354040] = {"火焰风暴中幸存","\n","Limitzero"},
[354041] = {"击碎噬骨者","\n","Limitzero"},
[354042] = {"顶级掠食者","\n","Limitzero"},
[354043] = {"不需要的耗材","\n","Limitzero"},
[354044] = {"解读护身符","\n","Limitzero"},
[354045] = {"对萨拉斯毫不留情","\n","Limitzero"},
[354046] = {"斯凯提斯闯入者","\n","Limitzero"},
[354047] = {"猎杀野外生物","\n","Limitzero"},
[354048] = {"失落帝国的魅力","\n","Limitzero"},
[354049] = {"埃匹希斯的历史：永恒之林","\n","Limitzero"},
[354050] = {"面对扭曲的野生动物","\n","Limitzero"},
[354051] = {"阴谋集团入侵","\n","Limitzero"},
[354052] = {"废除以太工坊","\n","Limitzero"},
[354053] = {"沙塔尔的救赎","\n","Limitzero"},
[354054] = {"精华萃取","\n","Limitzero"},
[354055] = {"暗影闯入者","\n","Limitzero"},
[354056] = {"压制斯凯提斯","\n","Limitzero"},
[354057] = {"击败巨兽","\n","Limitzero"},
[354058] = {"死神传说","\n","Limitzero"},
[354059] = {"德拉诺遗物","\n","Limitzero"},
[354060] = {"消灭沼泽生物","\n","Limitzero"},
[354061] = {"破坏幽暗沼泽","\n","Limitzero"},
[354062] = {"拆除黑潮","\n","Limitzero"},
[354063] = {"收缴武器","\n","Limitzero"},
[354064] = {"短命的蘑菇","\n","Limitzero"},
[354065] = {"消灭枯萎的生物","\n","Limitzero"},
[354066] = {"终结暗潮入侵","\n英雄，暗潮领地的邪恶纳迦对赞加沼泽的攻击越来越激烈。暗潮的海妖和监工一直在袭击我们的哨所，并俘虏我们的俘虏，让他们收割沼泽。我们必须迅速采取行动，在他们占领更多土地之前结束他们的攻击。我需要我们最强大的勇士前往暗潮领地，结束这些邪恶的袭击。杀死领导这些袭击的暗潮海妖和监工，其余的人就会败退到深渊。只有你有能力结束他们的侵略并恢复和平。赞加沼泽就靠你了!","Limitzero"},
[354067] = {"清除泻湖潜伏者","\n勇士，赞加沼泽的水道已经被危险的野生动物占领，威胁到该地区的贸易和旅行。黑暗之巅附近的泻湖里到处都是凶猛的鳗鱼、泻湖行者和九头蛇，它们会攻击任何敢于经过的人。我需要我们最强大的英雄冒险进入泻湖，在这些入侵物种完全占领水道之前将其消灭。杀死鳗鱼、行者和九头蛇，这样就可以再次恢复安全的旅行和贸易。赞加沼泽的人民指望你来恢复泻湖的安全。","Limitzero"},
[354068] = {"找出答案的一种方法","\n一位名叫米尔辛斯的女士对赞加玛什各种蘑菇的特性非常好奇，她向任何愿意接触该地区奇异蘑菇并汇报其效果的人提供奖励。她相对确定这些蘑菇都不会致命，并表示愿意亲自复活任何发现情况的人。","Limitzero"},
[354069] = {"采集样本","\n英雄，我正在研究赞加沼泽的野生动物，以便更好地了解沼泽生态系统的微妙平衡。为了完成我的研究，我需要健康生物和受该地区蔓延的枯萎病影响的生物的样本。请从赞加沼泽的健康野生动物和枯萎生物身上采集组织样本。你收集的样本将提供宝贵的见解，有助于恢复沼泽的活力。你今天的努力将对保护这个独特的环境产生持久的影响。赞加沼泽将因你的贡献而繁荣昌盛!","Limitzero"},
[354070] = {"瓦解血鳞部队","\n勇士，血鳞部落的邪恶纳迦在赞加沼泽建立了据点，威胁到该地区的稳定。来自血鳞之地的督军和唤浪者对我们的盟友发动袭击。我需要我们最强大的英雄潜入血鳞之地并从内部瓦解他们的军队。杀死他们的督军和唤浪者以破坏他们的指挥链。没有了领导，剩下的血鳞部落将别无选择，只能撤退。打破他们对沼泽的控制，恢复平衡。赞加沼泽就靠你了，英雄!","Limitzero"},
[354071] = {"削弱安葛洛什氏族","\n英雄，安葛洛什氏族的食人魔对赞加沼泽的攻击越来越激进。他们的萨满和战士从凿成沼泽的哨站袭击我们的定居点并破坏贸易路线。我需要你冒险前往凿成沼泽并终结安葛洛什的威胁。杀死他们的萨满以破坏他们的魔法，并消灭他们的战士以摧毁他们的战斗力。他们的氏族被击溃后，剩余的食人魔将撤退。只有你才有能力将他们赶回去并恢复赞加沼泽的稳定。","Limitzero"},
[354072] = {"深入沼泽","\n勇士，蛇湖中的野生动物已经变得非常危险，失去了平衡。疯狂的泥鳍鱼和沼泽爪鸫肆意繁殖，破坏了生态系统。我需要一位专业的沼泽潜水员深入蛇湖深处，在这些入侵物种淹没脆弱的沼泽栖息地之前将其消灭。杀死疯狂的泥鳍鱼和疯狂的沼泽爪鸫，恢复自然平衡。","Limitzero"},
[354073] = {"闪烁的光","\n英雄，据报道赞加沼泽的蛇湖附近出现了奇怪的闪光。这些光的来源尚不清楚，但它们似乎有意将我们引向某个地方，或者可能是某样东西。我需要你在事态进一步升级之前调查这些目击事件。在蛇湖附近区域搜索闪光的来源，看看你是否能发现它们的来源和用途。","Limitzero"},
[354074] = {"鱼肉大餐","\n贫民窟的食物供应正在减少。虽然外域某些地方食物匮乏，但赞加沼泽却拥有丰富的泥鳍鱼，虽然它们很危险，但如果捕获，可以作为一顿美餐。\n如果你能收集泥鳍鱼，那将是一项巨大的贡献。它们在蛇湖中数量众多，但该地区的纳迦和食人魔似乎也将它们用作食物来源，并且可能携带一些。","Limitzero"},
[354075] = {"孢子苗的防御","\n贫民窟的食物供应正在减少。虽然外域某些地方食物匮乏，但赞加沼泽却拥有丰富的泥鳍鱼，虽然它们很危险，但如果捕获，可以作为一顿美餐。\n如果你能收集泥鳍鱼，那将是一项巨大的贡献。它们在蛇湖中数量众多，但该地区的纳迦和食人魔似乎也将它们用作食物来源，并且可能携带一些。","Limitzero"},
[354076] = {"破坏血鳞","\n勇士，邪恶的血鳞纳迦在血鳞飞地建立了据点，并以此为基地劫掠和奴役赞加沼泽的人民。我们了解到，他们的大部分劫掠队伍都是由血鳞女巫带领的，奴隶主们控制着他们的 Wrekt 奴隶。我需要你潜入血鳞飞地，从内部消灭他们的劫掠力量。杀死他们的女巫以破坏他们的魔法，并消灭奴隶主以释放他们的俘虏。打破血鳞的控制，让赞加沼泽再次获得和平。","Limitzero"},
[354077] = {"蛮荒沼泽的威胁","\n英雄，蛮沼村的失落者已经失去平衡，现在威胁到了赞加沼泽的稳定。他们的德鲁伊、猎人和神秘主义者已经开始攻击我们在沼泽各地的盟友。我需要你前往蛮荒沼泽并消除威胁，以免更多无辜的生命丧生。杀死他们强大的德鲁伊、熟练的猎人和神秘的萨满。摧毁蛮荒沼泽的力量，这样才能恢复平衡。虽然他们无可救药，但我要求你在任务中表现出仁慈。为了赞加沼泽的利益，做该做的事。我相信你会成功的。","Limitzero"},
[354078] = {"保护孢子村","\n英雄，我们在孢子村的盟友在赞加沼泽持续的平衡斗争中遭受了巨大损失。许多孢子幼体受伤，他们的村庄遭到破坏。我需要一个像你一样富有同情心的人来照顾整个沼泽中受伤的孢子幼体。治愈你能找到的那些，并提供你力所能及的帮助。虽然任务看起来很小，但正是这样的仁慈之举往往能扭转局势，带来希望。孢子幼体的文化依赖于像你这样的英雄。请尽你所能保护孢子村。","Limitzero"},
[354079] = {"为了更好地利用","\n德莱尼人已经开始向破碎者学习萨满教的艺术，但他们中的许多人对此还不熟悉，还没有学会制作自己的图腾。我们没有办法为所有有抱负的德莱尼萨满制作图腾，但是赞加沼泽的纳迦和失落者都练习萨满教的艺术。虽然他们的图腾是由我们的敌人创造的，但他们可以更好地利用这些图腾。","Limitzero"},
[354080] = {"净化匕首沼泽","\n英雄，一股巨大的黑暗笼罩了匕首沼泽村，让这里的居民陷入疯狂。匕首沼泽的泥沼居民和刺客变得冷酷无情、嗜血成性，攻击任何靠近他们可恶村庄的人。我要求你前往匕首沼泽，在更多无辜者丧命之前消除这一威胁。杀死泥沼居民和刺客，让沼泽恢复平衡。这是一项艰巨的任务，但匕首沼泽现在已经无可救药了。","Limitzero"},
[354081] = {"破坏安葛洛什的势力","\n勇士，安葛洛什氏族的食人魔已经建立了一个要塞，威胁到了赞加沼泽的稳定。他们从安葛洛什要塞对我们的盟友发动了残酷的袭击。我需要你潜入要塞，从内部瓦解安葛洛什的势力。杀死他们的噬魂者，以破坏他们的黑暗仪式，然后消灭他们的屠夫，以摧毁氏族的军事力量。随着队伍的混乱，剩下的食人魔别无选择，只能撤退。只有像你这样的英雄才能结束安葛洛什的威胁。","Limitzero"},
[354082] = {"安葛洛什的入侵","\n英雄，安葛洛什氏族的食人魔变得更加大胆，从安葛洛什领地的哨站向我们在赞加沼泽的盟友发动攻击。他们的哨兵站岗，而野蛮的战士和黑暗的术士则进行无情的袭击。我需要你前往安葛洛什领地，制止他们的侵略。杀死他们的哨兵、战士和术士，以削弱他们的袭击队伍的力量。必须让安葛洛什食人魔明白，这种行为是不能容忍的。","Limitzero"},
[354083] = {"偷来的蘑菇","\n沼泽领主被迫攻击孢子幼虫以获取食物，而我们已经知道了原因。安格罗什食人魔正在收获它们通常以之为食的蘑菇，并将它们赶出家园。如果你从食人魔那里拿走它们，我们可以留下一些给沼泽领主，这样可能会消除它们对孢子幼虫的攻击性。","Limitzero"},
[354084] = {"无魂者","\n","Limitzero"},
[354085] = {"命运的围攻","\n勇士，燃烧军团已经围攻命运阶梯!邪能士兵、死亡低语者和一个邪恶的恐怖战术家率领着这次进攻。我们的侦察兵报告说，他们计划使用阶梯作为传送门，带来无尽的增援。我需要你冒险前往前线，趁还来得及的时候打破围攻!消灭邪能士兵，让低语的亡灵沉默，并杀死可怕的指挥官。外域的命运悬而未决。只有像你这样的英雄才能扭转局势，对抗燃烧军团。命运在召唤你——你会回应吗？","Limitzero"},
[354086] = {"扰乱军团势力","\n英雄，燃烧军团的军队在地狱火半岛的军团前线集结。愤怒守卫、末日低语者和邪能操控者正在准备开战。我们必须在他们壮大之前瓦解他们的队伍!我需要你袭击军团前线的心脏。消灭愤怒守卫，压制末日低语者，并净化邪能操控者。让他们的准备陷入混乱，并延缓他们的行动。外域的自由取决于能否立即阻止军团。你是我们最大的希望，勇士!瓦解他们的队伍，我们才能重整旗鼓。","Limitzero"},
[354087] = {"军团的痛苦","\n军团的痛苦","Limitzero"},
[354088] = {"军团的阴谋","\n军团的阴谋","Limitzero"},
[354089] = {"魔化能量","\n魔化能量","Limitzero"},
[354090] = {"削弱泽斯戈","\n英雄，泽斯戈的血环兽人是我们不能忽视的严重威胁。步兵、死灵法师和黑暗萨满正在为战争做准备。我们必须立即采取行动，在他们获得力量之前削弱他们的势力!我需要你潜入泽斯戈尔并从内部瓦解他们。消灭他们的步兵，阻止死灵法师的黑暗仪式，并杀死他们堕落的萨满。让他们手忙脚乱地重建家园。","Limitzero"},
[354091] = {"消灭被玷污的动物","\n勇士，黑暗魔法渗透了泽斯戈尔，将当地的野生动物变成了凶猛的野兽。疯狂的地狱野猪、饥饿的秃鹫和其他生物现在威胁着该地区。我不忍心看到他们受苦!杀死被玷污的地狱野猪、剥骨秃鹫和其他思想扭曲到无法挽救的动物。我知道这是一项艰巨的任务，但必须完成才能恢复平衡。地狱火需要像你这样富有同情心的英雄来做出艰难的选择。接受我的祝福吧。","Limitzero"},
[354092] = {"不屈军团","\n英雄，远征军军械库的诅咒之灵再次复活，成为不屈军团。很久以前，古尔丹的死亡骑士创造了这些不死士兵，并把他们束缚在自己的意志之下。如今，这些群龙无首的不屈骑士、巫师和步兵在军械库中游荡，对所有人都构成威胁。我们必须让他们安息!我需要你前往军械库，在更多无辜者受苦之前瓦解这个军团。消灭他们的骑士，阻止巫师的黑暗魔法，并消灭他们的步兵。将这些灵魂从不死的束缚中解放出来，让他们最终获得安宁。这是一项艰巨的任务，但只有你才能完成它。地狱之火就靠你了，勇士!","Limitzero"},
[354093] = {"测试治疗方法","\n英雄，炼金术士萨卡里已经研制出一种可以治愈地狱火野生动物的邪能变异的药膏。如果及早使用，这种药膏可以恢复清醒并治愈受影响的人。但是，我们必须先测试一下!冒险进入地狱火半岛，将药膏涂在任何表现出腐化的地狱野猪身上。仔细观察结果，然后返回并报告你的发现。","Limitzero"},
[354094] = {"夺回暗黑武器","\n勇士，地狱火的黑暗势力正在为即将到来的战役储备武器。不屈营囤积的幽灵武器和血窟氏族收集的沾满鲜血的武器可能对我们的战争努力至关重要。我需要你冒险进入远征军军械库和泽斯戈尔夺回这些黑暗武器。收集幽灵和沾满鲜血的武器并将它们带给我，这样它们就可以增强我们自己的力量。我们敌人的武器可能成为击败他们的工具。你今天的行动将武装我们的士兵，以应对未来的战斗。","Limitzero"},
[354095] = {"让碎手氏族陷入混乱","\n英雄，荣耀之路上的碎手兽人每天都在壮大。他们的步兵是他们部队的骨干，而术士和新手的力量和技能也在不断增强。如果不加以控制，他们将成为一股不可阻挡的力量。我要求你冒险前往荣耀之路，让这些兽人陷入混乱 - 杀死他们的战士、术士和新手，以破坏他们的组织。你今天的行动可能会给碎手部队造成沉重打击。","Limitzero"},
[354096] = {"破坏战果","\n英雄，碎手氏族在地狱火半岛肆无忌惮地发动战争。他们的守卫带领突袭队袭击要塞，而侍从和狂战士则变得越来越嗜血。如果我们不尽快阻止他们，他们的力量将无可匹敌。我要求你冒险进入半岛并帮助削弱他们的战争力量 - 杀死他们的守卫、侍从和狂战士以扰乱他们的行动。你今天的行动可能会扭转他们的势力。","Limitzero"},
[354097] = {"噬骨者残骸","\n英雄，噬骨兽人的残余势力仍然潜伏在地狱火半岛。他们的食腐者将土地洗劫一空，而劫掠者和召唤者则攻击所有挡路的人。如果不加以制止，他们会变得大胆，并重新组建自己的军队。我要求你追捕这些噬骨兽人 - 杀死他们的食腐者、召唤者和劫掠者，这样他们的部落就无法再立足。你今天的行动可以彻底消灭这个威胁。","Limitzero"},
[354098] = {"夺取邪能氏族的资源","\n英雄，邪能氏族的战争机器依靠遍布地狱火半岛的物资储备来提供动力。通过劫掠这些物资并将其据为己有，我们可以严重削弱他们的实力，同时增强我们自己的实力。我要求你冒险进入邪能氏族的领地，与他们的军队作战，并没收他们的物资。把它们带给我，这样我们的工匠就可以决定如何最好地利用它们来对付他们以前的主人。","Limitzero"},
[354099] = {"研究标本","\n一位名叫萨卡里的炼金术士想要研究地狱火半岛邪兽人身上流淌的腐化血液。通过收集堕落者的样本，她相信自己可以找到抵抗和消除恶魔污染的方法。我请你前往半岛，与这些邪兽人战斗，收集他们的血液。将这些样本带给我，这样萨卡里就可以进一步研究并找出这个敌人的弱点。","Limitzero"},
[354100] = {"安抚地下野兽","\n英雄，大裂隙中栖息的野兽变得越来越具有攻击性。石镰幼崽成群结队地攻击旅行者，而阿尔法则带领着残酷的狩猎。巨大的隧道者从深处涌出，恐吓着这片土地。如果不加以控制，它们的数量将激增到无法控制的程度。我要求你冒险进入裂缝并安抚这些地下野兽 - 屠杀幼崽、阿尔法和隧道者，以恢复平衡。","Limitzero"},
[354101] = {"突袭哈尔什","\n英雄，哈尔什部落的鸦人在哈尔什的巢穴中变得更加大胆。他们的风行者伏击所有经过的人，而利爪守卫则保持警惕。致命的卡利鸟从上空俯冲下来攻击。如果不加以制止，他们只会变得更加大胆。我要求你带领部队进攻哈尔什——杀死他们的风行者、利爪守卫和卡利鸟盟友，以结束他们的侵略。你今天的行动可能会给哈尔什军队造成沉重打击。","Limitzero"},
[354102] = {"地狱火掠食者","\n英雄，泰尔哈马特神庙附近的野生动物已经变得野蛮而不受控制。凶猛的秃鹫无休止地盘旋，而笨重的地狱野猪则肆无忌惮地冲锋。如果任由这些凶猛的掠食者自行其是，它们只会变得更加危险。我要求你削减它们的数量 - 冒险前去杀死秃鹫和地狱野猪，让这片土地恢复平衡。用弓、刀或法术，向这些地狱般的生物展示你的技能。","Limitzero"},
[354103] = {"打破枷锁","\n英雄，沙纳尔废墟中的恶魔伊利达雷将无辜者当作奴隶，无情地将他们锁在枷锁中。他们的哭喊声从废墟中传出，恳求救赎。我恳求你，勇敢的英雄，前往沙纳尔，打破这些枷锁——释放被奴役的人，让他们回到亲人身边。你的同情心和技能今天可以拯救许多人的生命。赶快行动，以免更多人遭受伊利达雷残酷的束缚。","Limitzero"},
[354104] = {"鸟类骨骼","\n英雄，我们的盟友正在研究栖息在地狱火半岛的鸟类和鸦人的不寻常骨骼。通过收集死者的样本，他们相信他们可以揭开有关其解剖学和进化的秘密。我要求你在整个半岛上与这些有翼生物战斗并收获它们的骨骼。把样本带给我，这样我们的盟友就可以进一步研究。你今天的努力可以为在这片陌生的土地上航行提供宝贵的知识。","Limitzero"},
[354105] = {"军团野心","\n勇士，不祥的消息来自基尔加丹的王座。炽热的邪能火花和愤怒使者聚集在一起，毫无疑问他们正计划将燃烧军团的势力扩展到外域。我们必须迅速采取行动，挫败他们的野心!我需要你前往王座，瓦解他们的军队。在邪能火花蔓延之前消灭它们，在使者们宣扬燃烧军团的谎言之前让他们闭嘴。打破他们对王座的控制，让地狱火重获希望。","Limitzero"},
[354106] = {"火焰入会仪式","\n英雄，我们的侦察兵报告称，基尔加丹王座处有令人不安的活动。燃烧军团准备让新的邪血战士参加烈焰仪式，以壮大他们的队伍。我们必须迅速采取行动来阻止这种情况发生!我需要你前往王座并阻止仪式。在邪血战士完成入会仪式之前将其杀死。如果有人逃脱，也不要绝望；延迟他们的入会仪式会削弱燃烧军团的力量。今天阻止新的烈焰战士可能会在未来的战斗中挽救无数生命。","Limitzero"},
[354107] = {"净化阿苟纳之池","\n勇士，黑暗势力在阿苟纳之池中集结。恐惧魔和蛆虫出现，被邪能扭曲成可怕的怪物。如果不加以控制，它们的数量将激增，威胁到整个地狱火!我需要你前往阿苟纳之池，在为时已晚之前清除这些恶魔。消灭在腐化水域中繁殖的恐惧魔和腐蛆虫。在毁灭蔓延到整个大陆之前，消灭它们。","Limitzero"},
[354108] = {"收割地狱火","\n勇士，我们在沙塔斯的盟友需要邪能余烬来为即将到来的战斗打造附魔武器。阿苟纳之池和基尔加丹王座充满了这种炽热的碎片，但收集它们非常危险。只有像你这样身手敏捷的英雄才能幸存下来。冒险进入池子和王座，收集尽可能多的邪能余烬。收集足够的邪​​能余烬进行最后的准备，这样我们的部队就可以装备精良地投入战场。","Limitzero"},
[354109] = {"恐怖盗贼","\n基尔加丹王座上的军团部队正在使用他们自己的成员，即在战斗中失败的恐怖守卫，作为能量源。他们通过该地区周围的复杂装置将恐怖守卫悬浮起来，并制造了更多装置，旨在从这些恶魔身上吸取能量，供沉迷于邪能的血精灵或他们自己的武器使用。\n但如果精灵能够使用他们的设备，那么我们相信我们也能将这种能量源用于我们自己的目的。在基尔加丹王座周围收集恐怖虹吸器，并使用它们从悬浮的恐怖守卫身上吸取能量。当你收集到足够的恐怖虹吸器时，就把它放回这里，小心，如果没有得到妥善控制，恶魔的力量是危险的。","Limitzero"},
[354110] = {"镇压军团","\n在督军托尔加卡的监督下，军团在影月谷的军团要塞组建了一支新的地狱火大军。这支大军随时准备穿越影月谷，摧毁我们在那里的据点。\n在军团做好充分准备之前，它们处于休眠状态，但邪能可以保护它们免受直接攻击，不过，我们可能找到了另一种解决方案。一位自称米尔辛斯的旅行萨满相信，如果军团用于保护的其中一个能量核心被添加到她的图腾能量中，她的图腾就可以扑灭地狱火的火焰并摧毁它们，即使它们被保护着。\n虽然她不想直接攻击军团要塞，但她已允许愿意摧毁这支军队的英雄借用她的图腾。拿上它，从军团要塞收集能量核心，让它绕过地狱火的防御。然后把它放在那里休眠的地狱火中间。米尔辛斯的魔法会完成剩下的工作。","Limitzero"},
[354111] = {"战胜黑暗议会","\n勇士，来自斯克瑟隆的可怕消息。黑暗议会聚集起来，利用黑暗魔法试图再次将他们的神带到这个世界。先驱者传播厄运，仪式者召唤黑暗，蔑视的乌鸦发出不祥的叫声。这不能容忍!我需要你立即前往斯克瑟隆并拆除议会。消灭他们的先驱，破坏仪式，让乌鸦沉默，并消灭那些向阴影宣誓效忠的人。让他们的野心化为废墟。只有我们最伟大的勇士才能成功对抗这种邪恶的魔法。圣光与你同在，英雄!","Limitzero"},
[354112] = {"根除日蚀","\n英雄，凯尔萨斯的日蚀之力在日蚀点日益强大。士兵们列队，法师们施展奥术魔法。科洛克的怪物儿子领导着他们所有人。如果我们不尽快面对他们，他们的下一次袭击可能会摧毁影月。我要求你前往日蚀点，消除日蚀之力的威胁 - 杀死他们的士兵、法师和邪恶的领袖。结束他们的黑暗统治，让影月获得和平。","Limitzero"},
[354113] = {"暗蛋狩猎","\n英雄，黑暗教团的卵似乎注入了他们神秘神灵的一部分力量。如果我们能安全地控制这些卵，我们的盟友也许能够发现他们亵渎的繁殖行为中的弱点。我需要你冒险进入斯克瑟隆并收集尽可能多的黑暗教团卵。处理它们时要小心!","Limitzero"},
[354114] = {"剥夺日蚀饰物","\n英雄，邪恶的日蚀血精灵用魔法吊坠来装饰自己，以引导邪恶能量。如果我们能获得这些吊坠的库存，我们的盟友可能会找到破坏他们魔法的方法。我需要你冒险进入日蚀点，从你击败的任何日蚀身上取下吊坠。小心不要自己戴上它们!把吊坠带给我，这样我们就可以找到一种方法来利用他们的力量来对付他们。","Limitzero"},
[354115] = {"驱逐库斯卡","\n勇士，库斯卡部落的邪恶纳迦已在库斯卡岗哨站稳脚跟，用黑暗魔法威胁影月。海妖、水之守护者、眼镜蛇和守卫者守住了这一地区，随时准备发起攻击。我们必须行动!我需要你立即前往库斯卡岗哨，在他们构成更大威胁之前瓦解他们的军队。消灭他们的海妖，阻止守护者的仪式，杀死他们的眼镜蛇，击溃他们的守卫者。将库斯卡赶回海里!","Limitzero"},
[354116] = {"库斯卡屠戮","\n英雄，库斯卡部落的纳迦变得大胆起来。他们的女巫、侍从和泥浆守卫者从蓄水池中向影月发起了无情的攻击。他们的侵略行径令人无法忍受!我需要你前往蓄水池，瓦解库斯卡军队。消灭他们的女巫，以破坏他们的魔法。杀死侍从，以摧毁他们的军事力量。消灭泥浆守卫者，以揭露他们的邪恶行径。消灭他们的队伍，让影月再次获得和平。","Limitzero"},
[354117] = {"大地、水流、火焰!","\n勇士，影月谷因愤怒的元素精灵肆意出现而颤抖。大地之灵搅动大地，水灵淹没河流，邪火怒焰熊熊燃烧。它们的不平衡威胁着​​我们所有人!我需要你穿越影月谷，制服这些疯狂的生物。镇压大地之灵，平息水流，扑灭火焰。在浩劫吞噬大地之前恢复平衡。","Limitzero"},
[354118] = {"夺取物资","\n英雄，我们的侦察兵报告称，库斯卡纳迦正在通过影月城运送资源，以支持他们的黑暗行动。拦截这些补给将对我们的敌人造成打击。我需要你秘密缴获你在影月城找到的所有库斯卡补给。获取他们的武器、仪式部件以及任何可能扰乱他们行动的东西。将补给带给我，这样我们就可以利用他们的资源来对付他们。","Limitzero"},
[354119] = {"元素材料","\n勇士，影月谷肆虐的元素能量可以被利用，只要有适当的材料和技巧。我们在沙塔斯的盟友想要制作附魔器具，但需要狂暴灵魂的精华。我谦虚地请求你在影月谷旅行期间收集火、水和土元素精华。从任何被击败的元素生物身上安全地提取它们。只收集那些你可以无害地运输的东西。有了这些精华，我们的工匠就可以锻造神器来对抗黑暗。我们最需要的是水器具，但幸运的是，该地区的纳迦也可能携带水精华。","Limitzero"},
[354120] = {"龙喉霸权","\n英雄，残忍的龙喉兽人从灵翼山脊征服了影月谷，甚至奴役了他们自己。升迁者用铁腕统治，执行军阀的意志。不服从的苦工渴望自由，脱离营地，使自己变得脆弱，而破天者则在全国范围内进行无情的袭击。我们不能袖手旁观!我需要你前往灵翼山脊，在龙喉队伍中挑拨离间。消灭升迁者，让传送器停飞以切断他们的补给，并杀死那些从团体中分裂出来的心怀不满的苦工。有了你的帮助，他们的控制最终可能会被打破!","Limitzero"},
[354121] = {"坍塌虚空矿洞","\n勇士，龙喉兽人在灵翼矿井毫不留情地剥削灵翼巨龙。当爆裂者和劫掠者恐吓巨龙和破碎奴隶，迫使他们屈服时，黑血从世界的中心渗出。我们不能允许这种残忍行为!我需要你潜入矿洞，从内部瓦解龙喉行动。净化黑血，消灭爆裂者和劫掠者。摧毁矿洞，让灵翼巨龙再次自由飞翔!我相信你会成功的。","Limitzero"},
[354122] = {"粉碎虚空鳐的浪潮","\n英雄，虚空之翼悬崖上出现了危机。愤怒的空气精灵陷入狂暴状态，驱使大量虚空鳐涌入该地区。如果不加以控制，这些入侵生物将摧毁悬崖!我需要你立即前往虚空之翼悬崖，粉碎这股浪潮。在情况恶化之前，平息狂暴的空气精灵并消灭成群的虚空鳐。只有我们最强大的勇士才有能力完成这项重要任务。悬崖的未来取决于你，英雄!","Limitzero"},
[354123] = {"夺取灵翼碎片","\n勇士，龙喉氏族使用结晶的灵翼碎片通过痛苦来控制被奴役的龙。如果我们能安全地控制这些碎片，我们的盟友相信他们就能找到如何破坏他们的控制。我需要你前往灵翼岩架并夺取你找到的任何灵翼碎片。处理它们时要小心!交付碎片将使我们的盟友能够解开他们的秘密，并可能释放灵翼军团。","Limitzero"},
[354124] = {"驾驭灵翼精华","\n勇士，灵翼龙拥有强大的天生魔法，即使是通过奴役。我们在沙塔斯的盟友相信研究它们的精华可以洞察新的魔法流派。我谦虚地请求你在灵翼岩架上旅行时收集灵翼精华样本。小心地从任何堕落的龙或生物身上提取它们。只取回你可以安全运输的东西。获得的知识可能有助于我们战胜邪恶并释放灵翼。你今天的行动可能会重塑外域及其他地方的魔法艺术!","Limitzero"},
[354125] = {"伊利达雷狱卒","\n勇士，有关看守牢笼的恶魔狱卒的黑暗谣言依然存在。伊利达雷在他们严酷的监狱里折磨着所有人，为他们的恶魔领袖提供灵魂。我们不能允许这样的罪恶发生!我需要你潜入牢笼并瓦解狱卒的队伍。杀死监督折磨的恐惧守卫。消灭他的狱卒和折磨者。打破伊利达雷的控制，这样笼子里的居民就可以得到释放。","Limitzero"},
[354126] = {"击退入侵的灰舌氏族","\n勇士，灰舌氏族已经对巴尔里废墟发起了入侵。灰舌氏族的萨满、战士和工人现在正爬在废墟中，威胁着要玷污这处神圣的德莱尼遗址。我们不能允许这种情况发生!我需要你立即前往废墟，击溃入侵部落。消灭他们的萨满，消灭他们的战士，摧毁他们的努力成果。将灰舌氏族赶回阴影中，这样才能恢复平衡。","Limitzero"},
[354127] = {"卡拉波巅峰之战","\n英雄，伊利丹的军队已经占领了卡拉波废墟。日怒根除者将邪火倾泻在圣地上，恶魔猎手新兵和祈求者则亵渎了神殿。我恳求你，勇敢的英雄，前往卡拉波，在神圣的废墟上战斗 - 杀死根除者、新兵和祈求者，夺回控制权。你今天的行动可以帮助夺回卡拉波的神圣殿堂。","Limitzero"},
[354128] = {"卡拉波的圣物匣","\n英雄，卡拉波废墟的圣物箱中仍残留着古代遗物。这些文物在召唤我们，渴望从凯尔萨斯的军队的亵渎中解救出来。我请求你前往废墟，从他的爪牙手中夺取这些圣物，并将它们安全带走。虽然卡拉波本身目前可能处于黑暗之中，但保护它的宝藏可以为它的复兴照亮道路。","Limitzero"},
[354129] = {"伊利达雷印记","\n英雄，邪恶的伊利达雷身上的印记充满了黑暗魔法和邪能。如果我们能收集到这些印记，我们的盟友相信他们可以利用它们的力量，想出办法来对抗伊利达雷的邪恶。我要求你去影月谷猎杀这些恶魔，夺取他们的印记，并把它们带给我。通过研究敌人的魔法，我们可能会发现他们的弱点。","Limitzero"},
[354130] = {"通缉：奥拉沃斯","\n夺取艾德拉斯废墟似乎与纳迦面临的挑战一样大。至少在某种意义上，这是我们想要夺取的上层精灵遗迹之一。\n我们了解到，上层精灵创造的守护构造体之一在经过这么长时间后仍然处于激活状态。他们称之为乌拉佛斯，尽管经过这么长时间，它似乎仍然很危险，并且仍然决心履行职责。\n即使我们通过了纳迦，只要奥拉沃斯仍然处于激活状态，我们就无法安全地派遣任何研究人员进入废墟，尽管这种构造体在完好无损时值得研究，但将其留在那里是我们无法承受的风险。因此，我们要求您深入艾德拉斯废墟并摧毁奥拉沃斯。","Limitzero"},
[354131] = {"亚考洛克的信徒","\n海神亚考洛克的追随者们渴望证明自己，他们与任何接近他神庙的人战斗，希望赢得神的青睐。虽然我们没有与亚考洛克本人战斗，但他过分热心的信徒们已经证明是该地区的一大祸患。\n我们请你前往神庙，亲自面对亚考洛克的信徒。","Limitzero"},
[354132] = {"风暴海湾的危险","\n我们的研究人员想要研究埃达拉之塔，这是艾萨拉上层精灵遗迹中少数几个未被纳迦占领的部分之一，但该地区到处都是鱼人、多头蛇和马克里尼，我们无法抽出足够的人手来保护该地区的研究人员。\n我们需要有人进入并清理风暴海湾地区，以便安全地研究那里的遗迹。","Limitzero"},
[354133] = {"雷霆峭壁","\n英雄，从苦涩之地传来消息，愤怒的巨人正在威胁旅行者。愤怒的峭壁行者沿着锯齿状的悬崖行走，而雷霆巨人则使风变得狂暴。必须平息他们的原始愤怒，以免更多无辜者受到伤害!我需要你前往苦涩之地并制服这些巨人。","Limitzero"},
[354134] = {"海神像","\n人们对居住在艾萨拉的半神亚考洛克知之甚少，但他神庙内和附近的许多生物似乎都崇拜他。我们想收集他的偶像，以便进一步研究他的宗教。\n神庙中的任何信徒可能都带着亚考洛克的偶像，但该地区周围的其他海洋生物似乎也以某种方式与他有关，因此我们相信其中一些生物可能也有偶像。","Limitzero"},
[354135] = {"雨水收集器","\n在亚考兰神庙周围，可以看到奇怪的水泡漂浮在触手可及的地方。我们的记录表明，这些水泡与亚考兰宗教有某种联系，但很难接触到这些水泡以了解更多信息。\n如果你能找到办法捕捉它们，那么如果你能捕捉几个并向我们报告你的发现，我们将不胜感激。","Limitzero"},
[354136] = {"通缉：阿卡拉什","\n通缉：阿卡拉什","Limitzero"},
[354137] = {"通缉：瓦尔克萨斯","\n通缉：瓦尔克萨斯","Limitzero"},
[412001] = {"大师级工匠：魔焰腰带","\n收集魔焰腰带","Limitzero"},
