[420451] = {"荣誉战斗：地下城 [高风险]","\n在菲拉斯的1v1荣誉战斗中消灭3名玩家。你和你的目标都必须处于宝藏猎人：地下城激活状态，才能获得击杀奖励。","Limitzero"},
[420452] = {"荣誉战斗：祖尔格拉布 [高风险]","\n在冬泉谷的1v1荣誉战斗中消灭3名玩家。你和你的目标都必须处于宝藏猎人：祖尔格拉布激活状态，才能获得击杀奖励。","Limitzero"},
[420453] = {"荣誉战斗：熔火之心 [高风险]","\n在冬泉谷的1v1荣誉战斗中消灭3名玩家。你和你的目标都必须处于宝藏猎人：熔火之心激活状态，才能获得击杀奖励。","Limitzero"},
[420454] = {"荣誉战斗：黑翼之巢 [高风险]","\n在西瘟疫之地的1v1荣誉战斗中消灭3名玩家。你和你的目标必须处于宝藏猎人：黑翼之巢激活状态，才能获得击杀奖励。","Limitzero"},
[420455] = {"荣誉战斗：安其拉 [高风险]","\n在西瘟疫之地的1v1荣誉战斗中消灭3名玩家。你和你的目标都必须处于宝藏猎人：安其拉激活状态，才能获得击杀奖励。","Limitzero"},
[420456] = {"荣誉战斗：纳克萨玛斯 [高风险]","\n在西瘟疫之地的1v1荣誉战斗中消灭3名玩家。你和你的目标都必须处于宝藏猎人：纳克萨玛斯激活状态，才能获得击杀奖励。","Limitzero"},
[420457] = {"荣誉战斗：奥妮克希亚 [高风险]","\n在冬泉谷的1v1荣誉战斗中消灭3名玩家。你和你的目标都必须处于宝藏猎人：奥妮克希亚激活状态，才能获得击杀奖励。","Limitzero"},
[420458] = {"荣誉战斗：外域地下城 [高风险]","\n在冬泉谷的1v1荣誉战斗中消灭3名玩家。你和你的目标都必须处于宝藏猎人：外域地下城激活状态，才能获得击杀奖励。","Limitzero"},
[420459] = {"荣誉战斗：英雄外域地下城 [高风险]","\n在冬泉谷的1v1荣誉战斗中消灭3名玩家。你和你的目标都必须处于宝藏猎人：英雄外域地下城激活状态，才能获得击杀奖励。","Limitzero"},
[420460] = {"荣誉战斗：卡拉赞 [高风险]","\n在冬泉谷的1v1荣誉战斗中消灭3名玩家。你和你的目标都必须处于宝藏猎人：卡拉赞激活状态，才能获得击杀奖励。","Limitzero"},
[420461] = {"荣誉战斗：[高风险]","\n在冬泉谷的1v1荣誉战斗中消灭3名玩家。你和你的目标都必须处于宝藏猎人：卡拉赞激活状态，才能获得击杀奖励。","Limitzero"},
