[580134] = {"飞升之路：神秘精华","\n在任何神秘祭坛上重铸神秘卷轴，提升神秘附魔等级，并获得神秘精华。","Limitzero"},
[580135] = {"飞升之路：神秘附魔收藏","\n在神秘祭坛中选择一个带有你希望提取的神秘附魔的神秘卷轴，然后单击保存到收藏，将魔法永久添加到你的神秘收藏中。","Limitzero"},
[580136] = {"飞升之路：幻化拍卖","\n在拍卖行搜索并买断任意稀有度为幻化的武器。","Limitzero"},
[580137] = {"飞升之路：改变你的外观","\n在主城拍卖行内的玛拉兹处转化任意物品。","Limitzero"},
[580138] = {"飞升之路：终极游戏构建","\n打开英雄构装师，载入一个70级的构装。","Limitzero"},
[580139] = {"飞升之路：PvE强度","\n在每个装备栏位中装备灵魂绑定装备，达到460PVE装备等级。","Limitzero"},
[580140] = {"飞升之路：PvP强度","\n在每个装备栏位中装备PVP或邪铸装备，以达到250PVP装备等级。","Limitzero"},
[580141] = {"飞升之路：装备起来!","\n装备更强大的装备，达到40装备等级。","Limitzero"},
[580142] = {"飞升之路：史诗神秘附魔收集","\n提取3个史诗级附魔，将其永久加入你的收藏。","Limitzero"},
[580143] = {"飞升之路：传说神秘附魔收集","\n提取1个传说级附魔，将其永久加入你的收藏。","Limitzero"},
[580144] = {"飞升之路：深入地下城","\n打开地下城查找器，排队进入随机普通地下城或选择任意可用的特定地下城。\n你可以独自排队进入地下城，也可以与部分团队一起排队，或者找一个完整的玩家团队。\n与你的队伍一起在地下城中奋战，击败任意正常地下城的最终首领。\n此任务在史诗和英雄地下城中无法完成。","Limitzero"},
[580145] = {"飞升之路：英雄地下城","\n在任意英雄地下城中击败最终首领。","Limitzero"},
[580146] = {"飞升之路：普通团队副本","\n在任意普通团队副本中击败最终首领。","Limitzero"},
[580147] = {"飞升之路：史诗地下城","\n在任意史诗地下城中击败最终首领。","Limitzero"},
[580148] = {"飞升之路：史诗+地下城","\n完成任意史诗+地下城。","Limitzero"},
[580149] = {"飞升之路：英雄团队副本","\n在任意英雄团队副本中击败最终首领。","Limitzero"},
[580162] = {"飞升之路：飞升团队副本","\n在任意飞升团队副本中击败最终首领。","Limitzero"},
[580163] = {"飞升之路：血铸","\n血铸一件装备。（诺兹多姆买血碗，使用血碗）","Limitzero"},
[580164] = {"飞升之路：血铸拍卖行","\n从拍卖行买断任意一件血铸装备。","Limitzero"},
[580165] = {"飞升之路：战场!","\n排队并完成任意战场!","Limitzero"},
[580166] = {"飞升之路：2v2 单挑 队列","\n使用单人排队加入2v2竞技场游戏。","Limitzero"},
[580167] = {"飞升之路：与竞技场商人交谈","\n访问并查看任意竞技场供应商的商品。","Limitzero"},
[580168] = {"飞升之路：少一些奔跑,多一些休息","\n下次死亡时，在最近的城镇或主城施放复活术。","Limitzero"},
[580169] = {"飞升之路：神秘附魔收藏","\n为你的收藏添加10件神秘附魔。","Limitzero"},
[580170] = {"飞升之路：史诗骑术","\n获得史诗骑术。","Limitzero"},
[580171] = {"飞升之路：专精 II","\n学习第二专业。","Limitzero"},
[580172] = {"飞升之路：集市令牌","\n获得1个集市令牌。","Limitzero"},
[580173] = {"飞升之路：虚灵集市","\n从虚灵集市购买任意物品。","Limitzero"},
[580174] = {"飞升之路：一流的实验传送器","\n使用一流的实验传送器。","Limitzero"},
[580175] = {"飞升之路：战争游戏","\n完成任意战争游戏。","Limitzero"},
[580176] = {"飞升之路：泰坦卷轴","\n使用任意泰坦卷轴。","Limitzero"},
[580178] = {"飞升之路：打倒阵营首领","\n消灭任意阵营首领。","Limitzero"},
[580179] = {"飞升之路：打倒世界首领","\n消灭任意世界首领。","Limitzero"},
[580180] = {"飞升之路：血战","\n在血战中消灭1名玩家。","Limitzero"},
[580181] = {"飞升之路：完成一场入侵","\n打败入侵首领。","Limitzero"},
[580182] = {"飞升之路：使用神秘附魔","\n激活神秘卷轴并将其应用到打开的附魔栏位中。","Limitzero"},
[580183] = {"飞升之路：重生","\n从克罗米处获得并使用重生功能。这将使你重置为1级。","Limitzero"},
[580185] = {"飞升之路：激活传说之力","\n在祭坛激活传奇秘法附魔!你可以重铸卷轴、搜索拍卖行或在世界中寻找传奇附魔卷轴。\n传奇附魔：\n- 提供巨大的力量提升\n- 可以解锁全新的原型和玩法\n- 一次只能激活一个\n你选择的传奇附魔将对你的游戏风格和力量产生重大影响。你可以随时在祭坛更换你的传奇附魔，所以尽情尝试和实验新事物吧!","Limitzero"},
[580186] = {"飞升之路：插满的神秘附魔","\n插满所有神秘附魔槽","Limitzero"},
[580187] = {"飞升之路：激活传说神秘附魔","\n激活传说神秘附魔","Limitzero"},
[580188] = {"飞升之路：激活史诗神秘附魔","\n激活史诗神秘附魔","Limitzero"},
[580189] = {"飞升之路：神秘附魔专精页","\n切换神秘附魔专精页","Limitzero"},
[580193] = {"飞升之路：插满的神秘附魔","\n插满所有神秘附魔槽","Limitzero"},
[580194] = {"飞升之路：神秘附魔收藏","\n打开神秘附魔收藏","Limitzero"},
[580195] = {"飞升之路狂野抽卡模式：重抽法术","\n按N选中法术点击unlearn（遗忘）进行重抽","Limitzero"},
[580196] = {"飞升之路狂野抽卡模式：重抽天赋","\n按N选中天赋点击unlearn（遗忘）进行重抽","Limitzero"},
[580201] = {"飞升之路狂野抽卡：激活一张技能卡","\n按N在卡牌界面激活一张技能卡","Limitzero"},
[580204] = {"飞升之路：插满的神秘附魔","\n插满所有神秘附魔槽","Limitzero"},
[580208] = {"飞升之路：击败拉格纳罗斯","\n击败拉格纳罗斯","Limitzero"},
[580209] = {"飞升之路：普通难度 - 奥妮克希亚（香草）","\n击败普通难度 - 奥妮克希亚（香草）","Limitzero"},
