[980268] = {"赞加沼泽战争：暗泽村 （高风险）","\n萨博迈恩男爵悬赏捉拿暗泽村的精灵。挑战其中的虚灵可不是一场轻而易举的战斗。萨博迈恩希望我们帮助他击败暗泽村的敌人。前往泰罗卡领取赏金，但要注意，你并不是唯一接受这份合约的冒险者。你应该准备好在狩猎过程中与竞争对手一决高下!","Limitzero"},
