[981220] = {"为了部落：进入生态圆顶","\n在中央生态圆顶内猎杀野生动物。","Limitzero"},
[981221] = {"为了部落：击溃破坏者","\n在虚空石击杀克拉斯卡尔和法兰伦击碎者。","Limitzero"},
[981222] = {"为了部落：你的就是我的","\n清理法力熔炉：艾拉下方的特雷卢姆矿井和法力熔炉：乌提斯下方的瑟安竖井。","Limitzero"},
[981223] = {"为了部落：战争锻造","\n清理法力熔炉：杜隆和法力熔炉：库鲁恩的军队。","Limitzero"},
[981228] = {"为了部落：放干蓄水池","\n消灭库斯卡水池的纳迦。","Limitzero"},
[981229] = {"为了部落：我是死神,熔炉的毁灭者","\n攻击死亡熔炉消灭死亡熔炉守护者，从召唤师那里收集召唤者斯卡塔克斯的法杖和扭曲灵魂碎片。","Limitzero"},
[981230] = {"为了部落：伊利达雷恶魔狩猎","\n击败卡拉伯尔废墟中的恶魔猎手大师。","Limitzero"},
[981231] = {"为了部落：操作飞升","\n在灵翼浮岛屠杀龙喉苦工和龙喉晋升者。","Limitzero"},
[981232] = {"纳格兰战争：水晶解决方案","\n消灭沃舒古外的维尔埃尼虚灵。","Limitzero"},
[981233] = {"纳格兰战争：阴影之地","\n在沃舒古外消灭空灵爪牙。","Limitzero"},
[981234] = {"纳格兰战争：埋葬巨石之拳","\n在北风裂谷和南风裂谷消灭石拳食人魔。","Limitzero"},
[981235] = {"纳格兰战争：淤泥","\n消灭哈兰下面的泥泞爪牙。","Limitzero"},
[981236] = {"纳格兰战争：春季大扫除","\n在日泉岗哨消灭暗血敌人。","Limitzero"},
[981237] = {"刀锋山战争：巫妖卢安","\n消灭居住在卢安鸦巢的卢安鸦人和黑翼拜龙教徒。","Limitzero"},
[981238] = {"刀锋山战争：血谷","\n消灭居住在血槌深谷的血槌食人魔。","Limitzero"},
[981239] = {"刀锋山战争：晶歌山脉","\n消灭居住在刀锋山的小型虚空幼龙和水晶剥石者。","Limitzero"},
[981240] = {"刀锋山战争：鸦人突袭","\n消灭居住在维克鸦巢的鸦人。","Limitzero"},
[981241] = {"刀塔的战争：乌鸦林游侠","\n消灭居住在乌鸦林的砾石食人魔和黑翼拜龙教徒。","Limitzero"},
[981242] = {"虚空风暴战争：100%优质工程","\n消灭甘尔葛工程师和莫尔葛铁匠。","Limitzero"},
[981243] = {"虚空风暴战争：废墟有眼","\n向居住在法拉隆废墟的库鲁萨斯的猎犬和库鲁萨斯之眼复仇。","Limitzero"},
[981244] = {"虚空风暴战争：计划报废","\n消灭居住在机甲废场的萨克希斯虚灵。","Limitzero"},
