[981246] = {"虚空风暴战争：废墟袭击者","\n在恩卡亚特废墟中消灭空洞的德莱尼，在阿尔科隆废墟消灭阿尔科隆恶魔。","Limitzero"},
[981247] = {"影月战争：这是一场挑战","\n消灭巴尔里废墟的伊利达雷监工。","Limitzero"},
[981248] = {"影月战争：海妖警报","\n消灭居住在库斯卡岗哨的库斯卡海妖。","Limitzero"},
[981249] = {"影月战争：磁化狩猎","\n屠杀居住在熔岩平原的魔火双帆龙和魔能野猪。","Limitzero"},
[981250] = {"影月战争：你有积分吗?","\n消灭居住在伊利达雷岗哨的伊利达雷恶魔。","Limitzero"},
[981251] = {"影月战争：突击龙喉","\n消灭居住在龙喉要塞的龙喉兽人。","Limitzero"},
[982104] = {"入侵纳格兰：恐怖血统","\n刺杀征服者瓦兹希尔，并在沃舒古消灭恐怖卫兵。","Limitzero"},
[982105] = {"入侵纳格兰：馊主意","\n在嘲颅废墟刺杀顾问佐尔布和战槌食人魔。","Limitzero"},
[982106] = {"入侵纳格兰：山脊战争","\n消灭暮光山脊的死影教徒。","Limitzero"},
[982107] = {"入侵纳格兰：仇恨与恐惧","\n在铸魔营地：憎恨和铸魔营地：惊骇中消灭铸魔营地监工及其追随者。","Limitzero"},
[982112] = {"入侵刀锋山：艰巨的任务","\n刺杀格鲁尔巢穴外的刀塔食人魔。","Limitzero"},
[982113] = {"入侵刀锋山：死亡陷阱","\n在死亡之门处决犬王拜尔蒙和他的爪牙。","Limitzero"},
