[982249] = {"入侵影月谷：磁化狩猎","\n屠杀居住在熔岩平原的魔火双帆龙和魔能野猪。","Limitzero"},
[982250] = {"入侵影月谷：你有积分吗?","\n消灭居住在伊利达雷岗哨的伊利达雷恶魔。","Limitzero"},
[982251] = {"入侵影月谷：突击龙喉","\n消灭居住在龙喉要塞的龙喉兽人。","Limitzero"},
[1005014] = {"特殊事件：全球变热","\n请所有英雄注意!\n特殊事件需要特殊个人。安戈洛的火羽山似乎正在爆发。所有萨满都试图告诉我们这将是一个问题，但他们没有提出更合理的建议，这是他们的错……我的意思是，把我们的英雄献祭给火山？他们还能说得更不合理吗……？\n无论如何，我们真的不想承认他们是对的，所以我们正在寻找任何英雄来解决这个问题，即使只是暂时的。\n（此任务需要激活特定的循环事件才能完成）","Limitzero"},
[1005015] = {"特殊事件：减少族群","\n情报显示，黑手一直在尝试改变外交手段。荒谬吧？!\n黑手部队的力量在于他们的刺客，他们最近接到命令，不得滥杀路人。让我们一石二鸟。\n去消灭一些黑手部队，引诱他们的刺客。一旦你杀死了 10 名黑手刺客，回来领取你的奖励。\n（此任务需要激活特定的循环事件才能完成）","Limitzero"},
[1005016] = {"特殊事件：法力不足","\n英雄，城市奥术师有了惊人的新发现!\n我们可以为我们的战士注入奥术力量，使他们在战场上的战斗力提高 10 倍!最重要的是，它似乎有 30% 的成功率，而那些失败的人通常没有资格起诉，或者做任何事情。\n无论如何，我们的工作遇到了一个问题，我们所有的奥术师似乎都耗尽了法力。幸运的是，我们可以使用另一种法力来源来补充。艾萨拉的一些血精灵拥有如此多的法力，以至于当他们死亡时，他们实际上会创造出活生生的法力!\n你可以负责杀戮。去消灭一些血精灵，并消灭那些过早死亡的法力幽灵。我们会派人去收集核心。\n（此任务需要激活特定的循环事件才能完成）","Limitzero"},
[1005017] = {"特殊事件：为了光明","\n所有英雄们注意了!\n各地善良的人们都被暗影誓言教徒的可恶行径所激怒。显然，这些异教徒一直在玩弄某种奇怪的咒语，让他们的灵魂成为某种奇怪的阴暗实体的容器。\n杀死暗影誓言教徒，击倒他们英年早逝后出现的阴暗构造体。\n（此任务需要激活特定的循环事件才能完成）","Limitzero"},
[1005018] = {"特殊事件：全球变暖","\n嘿，英雄们，我又听到了一个疯狂的谣言!显然，暮光教徒一直在玩弄他们根本不理解的元素力量。我的一个朋友告诉我，一些原始元素对他们扭曲自然的行为感到不满。很搞笑，对吧？\n好吧，去那里看看总不会有什么坏处，对吧？去希利苏斯杀死一些暮光教徒和他们的狂暴大地元素。然后我们看看是否有什么变化。再说一次，不会有变化!看看就好了，不过我认为什么都不会发生……\n（此任务需要激活特定的循环事件才能完成）","Limitzero"},
[1005019] = {"特殊事件：一次无伤大雅的恶作剧","\n嘿，英雄们!我相信当这一切平息后，每个人都会对此一笑置之，但我和一些朋友认为给冬泉谷的熊怪一些烈酒会很有趣。一开始感觉很棒!熊怪们都吓坏了，不知道这会对他们造成什么影响。然而，他们似乎找到了某种剂量的最佳点……\n是的，有趣的是，英雄们，他们最终用它让自己的力量增加了十倍，甚至还学会了在哪里可以找到这种东西……后来，路人死了几个，我想我应该把这个贴在这里……所以如果你能杀掉几个熊怪，让他们用完他们的存货，然后杀死烈酒含量高的熊怪。\n（此任务需要激活特定的循环事件才能完成）","Limitzero"},
[1005020] = {"特殊事件：你将成为阿尔萨斯","\n东瘟疫之地的血色十字军似乎感染了某种瘟疫。他们中的许多人生病了，死后变成了无意识的死者。\n阿尔萨斯曾经面临同样的困境，他净化了整个斯坦索姆城，以阻止瘟疫蔓延。阿尔萨斯，你会成为一个伟大的阿尔萨斯!阿尔萨斯，去杀死被感染的猩红者以及随之而来的无意识死者。如果你及时完成任务，阿尔萨斯，除了奖励之外，你甚至可能晋升为大阿尔萨斯，阿尔萨斯，阿尔萨斯!\n（此任务需要激活特定的循环事件才能完成）","Limitzero"},
[1005021] = {"特殊事件：一个可怕的问题","\n前往东瘟疫之地杀死10个恶鬼后，回来领取奖励。\n（此任务需要激活特定的循环事件才能完成）","Limitzero"},
[1005022] = {"特殊事件：火热的不平衡","\n前往安戈洛环形山杀死40个燃烧入侵者，然后回来领取你的奖励。\n（此任务需要特定的轮换事件才能完成）","Limitzero"},
[1005023] = {"特殊事件：雨,雨,快走开!","\n前往艾萨拉杀死40个雷霆入侵者。\n（此任务需要特定的循环事件激活才能完成）","Limitzero"},
[1005024] = {"特殊事件：新冰河时代","\n前往冬泉谷并杀死 40 个水流入侵者\n（此任务需要激活特定的轮换事件才能完成）","Limitzero"},
[1005025] = {"特殊事件：飓风季","\n我发誓，这些萨满都是白痴。显然全球变暖是一个问题。然后我们将迎来一个新的冰河时代。但显然，他们没有提到遍布希利苏斯的大规模沙尘暴!如果他们不能将这些东西识别为问题，我们为什么要雇佣他们？!\n去希利苏斯杀死一些旋风入侵者，然后回来领取你的奖励。\n（此任务需要特定的循环事件激活才能完成）","Limitzero"},
[1005026] = {"非凡事件：古拉巴什之血","\n在古拉巴什血战中消灭40名玩家。\n（此任务需要特殊循环事件激活才能完成）","Limitzero"},
[1005027] = {"特殊事件：贪婪的恶魔","\n所有英雄们注意了!\n恶魔四处横行，偷走了我们所有贵重物品。杀死其中一个贪婪恶魔，你不仅可以得到它收集的一切，还可以得到城市的丰厚奖励。\n（此任务需要特定的循环事件激活才能完成）","Limitzero"},
[1005028] = {"末日：其拉威胁","\n所有英雄们注意了!\n其拉势力突然出现，现在全员出动。我们正在寻找所有英雄参与消灭这些其拉水晶及其守护者的行动。帮助摧毁其中一个水晶，然后回来领取奖励!","Limitzero"},
[1005029] = {"末日：天灾入侵","\n所有英雄们注意了!\n天灾军团和他们的信徒从天而降!击败天灾军团入侵者，回来领取你的奖励。","Limitzero"},
[1005030] = {"微妙情况： 铜矿石","\n收集20份铜矿石。","Limitzero"},
[1005032] = {"微妙情况： 铁矿石","\n收集20份铁矿石。","Limitzero"},
[1005033] = {"微妙情况： 银矿石","\n收集7份银矿石。","Limitzero"},
[1005034] = {"微妙情况： 金矿石","\n收集10份金矿石。","Limitzero"},
[1005035] = {"微妙情况： 秘银矿石","\n收集30份秘银矿石。","Limitzero"},
[1005036] = {"微妙情况： 真银矿石","\n收集15份真银矿石。","Limitzero"},
[1005037] = {"微妙情况： 瑟银矿石","\n收集20份瑟银矿石。","Limitzero"},
