[1007015] = {"招募英雄：旧希尔斯布莱德丘陵 (英雄)","\n保护时间秩序，消灭时空猎手。","Limitzero"},
[1007016] = {"招募英雄：黑色沼泽 （英雄）","\n保护时间秩序，消灭埃欧努斯。","Limitzero"},
[1007017] = {"英雄的召唤：卡拉赞","\n将玛克扎尔王子驱逐出卡拉赞!","Limitzero"},
[1007018] = {"英雄的召唤：祖阿曼","\n阿曼尼森林巨魔因其大胆的团队而被称为昭著。祖尔金是负责团队奎尔萨拉斯的督军，尽管巨魔已被高等精灵蹂躏殆尽。他又在祖阿曼建立了自己的军队。别搞错了。。。如果祖尔金开始团队，那将是毁灭性的杀了祖尔金。没有了督军，巨魔军队将不再是威胁。","Limitzero"},
[1007019] = {"英雄的召唤：格鲁尔之巢","\n消灭屠龙者格鲁尔。","Limitzero"},
[1007020] = {"英雄的召唤：玛瑟里顿的巢穴","\n洒尽玛瑟里顿的鲜血。","Limitzero"},
[1007021] = {"英雄的召唤：毒蛇神殿洞穴","\n干掉瓦丝琪<盘牙女王>。","Limitzero"},
[1007022] = {"英雄的召唤：风暴要塞","\n征服凯尔萨斯。","Limitzero"},
[1007023] = {"英雄的召唤：海加尔山之战","\n把阿克蒙德留在过去。","Limitzero"},
[1007024] = {"英雄的召唤：黑暗神庙","\n消灭伊利丹","Limitzero"},
[1007025] = {"英雄的召唤：太阳之井高地","\n千百年来，太阳井为高阶精灵的强大魔法提供了燃料。燃烧军团将一切都献给了这个古老的力量源泉，因为有了它，他们就有办法召集出他们的指挥官基尔杰顿。如果基尔加丹上场，我们必死无疑。但燃烧军团也给了我们在这场战争中给予决定性一击的机会。就是它了，英雄。打败燃烧军团。","Limitzero"},
[1007027] = {"遏制邪恶：入侵点大灾变","\n消灭8个灾难监工和6个魔能机甲斥候。","Limitzero"},
