[1700101] = {"安其拉开门事件：背叛","\n在希利苏斯消灭其拉部队!此任务奖励丰厚，你只能在今天从希拉斯・暗月处获得它。","Limitzero"},
[1903513] = {"飞升之路：寻求力量","\n从邮件中获取神秘附魔用品。通过获得失去光泽的神秘卷轴来制作神秘附魔，并使用神秘祭坛将其重铸成新的附魔。","Limitzero"},
[1903549] = {"飞升之路：混合危险","\n混合风险系统 NPC 可以在主要城市和藏宝海湾和沙塔斯等许多中立城市找到。\n无风险允许跨阵营 PvP，死亡后不会获得战利品。\n无风险 PvE 完全禁用 PvP，因此您无法攻击或被其他玩家攻击。\n要选择加入 PvE 模式，请选择无风险，然后选择 PvE 模式。\n高风险是世界上其自己的单独阶段，这意味着您不会遇到无风险玩家。在高风险中，当您在 1 级区域被杀死时，您会从包中掉落物品。如果您在 2 级或 3 级区域被杀死，您还会掉落装备好的战利品!\n进入高风险时，您将默认为阵营的忠诚成员。您可以施放雇佣兵以成为中立者，这样您就可以攻击和被任何人攻击，但也可以启用跨阵营高风险分组。您可以在主城中随时通过施放法术书常规选项卡中的法术在雇佣兵和部落或联盟之间切换。\n您可以随时在混合风险 NPC 处更改风险模式。与混合风险 NPC 交谈并选择无风险 PvP、无风险 PvE 或高风险 PvP。","Limitzero"},
[1903550] = {"飞升之路：混合危险","\n混合风险系统 NPC 可以在主要城市和藏宝海湾和沙塔斯等许多中立城市找到。\n无风险允许跨阵营 PvP，死亡后不会获得战利品。\n无风险 PvE 完全禁用 PvP，因此您无法攻击或被其他玩家攻击。\n要选择加入 PvE 模式，请选择无风险，然后选择 PvE 模式。\n高风险是世界上其自己的单独阶段，这意味着您不会遇到无风险玩家。在高风险中，当您在 1 级区域被杀死时，您会从包中掉落物品。如果您在 2 级或 3 级区域被杀死，您还会掉落装备好的战利品!\n进入高风险时，您将默认为阵营的忠诚成员。您可以施放雇佣兵以成为中立者，这样您就可以攻击和被任何人攻击，但也可以启用跨阵营高风险分组。您可以在主城中随时通过施放法术书常规选项卡中的法术在雇佣兵和部落或联盟之间切换。\n您可以随时在混合风险 NPC 处更改风险模式。与混合风险 NPC 交谈并选择无风险 PvP、无风险 PvE 或高风险 PvP。","Limitzero"},
[1903551] = {"飞升之路：邪能通信传送门","\n前往奥格瑞玛内阴影裂隙中的邪能通信传送门。","Limitzero"},
[1903552] = {"飞升之路：邪能通信传送门","\n前往暴风城法师区已宰的羔羊旅店，拜访地下室邪能通信传送门。","Limitzero"},
[1903553] = {"飞升之路：地下城搜索器","\n点击I或单击选项菜单中的绿眼图标打开地下城搜索器，选择一个地下城并单击查找小队。","Limitzero"},
